(window.GIM_TS=window.GIM_TS||{})["Nedarim.6"]={"from":144,"a":[["\u0003שומרת יבם,\u0004 אשה שמת בעלה בלא בנים והיא מצפה (\"שומרת\") שהיבם (אחי הבעל) ישאנה לאשה (ייבמה) או יחלוץ לה, \u0003בין\u0004 שהיתה שומרת \u0003ליבם אחד,\u0004 שהיה לבעלה רק אח אחד, \u0003בין לשני יבמין,\u0004 שהיו לו שני אחים או יותר, ומן הדין כל אחד מהם יכול לייבמה וזקוקה היא לו לייבום. \u0003ר' אליעזר אומר: יפר\u0004 היבם את נדריה. \u0003ר' יהושע אומר:\u0004 אם היתה שומרת \u0003לאחד —\u0004 יכול הוא להפר, \u0003אבל לא לשנים\u0004 שאין כל אחד מהם יכול להפר. \u0003ר' עקיבא אומר: לא לאחד ולא לשנים.\u0004","ומביאים מקצת מדיוניהם, \u0003אמר ר' אליעזר: מה אם אשה שקנה הוא לעצמו\u0004 על ידי קידושין — \u0003הרי הוא מיפר\u0004 את \u0003נדריה, אשה\u0004 יבמה זו \u0003שהקנו לו מן השמים\u0004 שהרי היא אשתו על פי גזירת הכתוב — \u0003אינו דין שיפר\u0004 את \u0003נדריה?\u0004","\u0003אמר לו ר' עקיבא:\u0004 יש לפרוך קל וחומר זה, כך: \u0003לא, אם אמרת באשה שקנה הוא לעצמו —\u0004 \u0003שאין לאחרים בה רשות\u0004 שהרי היא מוקנית לו לבדו ולא לאחר, \u0003תאמר באשה שהקנו לו מן השמים, שיש לאחרים בה רשות?!\u0004 שאם יש יבם נוסף, היא ממתינה לשני כמו לו.","\u0003אמר לו ר' יהושע: עקיבא, דבריך\u0004 נכונים \u0003בשני יבמין, מה אתה משיב על יבם אחד? אמר לו\u0004 ר' עקיבא: מכל מקום \u0003אין היבמה\u0004 נחשבת אשה \u0003גמורה ליבם כשם שהארוסה גמורה לאישה.\u0004","מנסים לברר את השיטות: \u0003בשלמא\u0004 \u0005[נניח]\u0006 \u0003ר' עקיבא סבר\u0004 \u0005[סבור]\u0006 ש\u0003אין זיקה,\u0004 כלומר, אין אומרים שחובת הייבום עצמה יוצרת קשר (\"זיקה\") שהוא כעין קשר נישואין בין האיש והאשה, ומשום כך אין היבם מפר את נדרי יבמתו. \u0003ור' יהושע סבר\u0004 \u0005[סבור]\u0006 ש\u0003יש זיקה,\u0004 ולכן כיון שהיא זקוקה ליבם אחד בלבד — הרי היא נחשבת כאשתו, ומפר את נדריה. \u0003אלא ר' אליעזר, מאי טעמיה\u0004 \u0005[מה טעמו]\u0006? \u0003אי\u0004 \u0005[אם]\u0006 סבור הוא ש\u0003יש זיקה,\u0004 מכל מקום \u0003אין ברירה.\u0004 שהרי עדיין לא התברר מי מהם יהיה בעלה, ואם כן כיצד יכול כל אחד מהם להפר לה?","\u0003אמר ר' אמי:\u0004 כאן מדובר \u0003כגון שעשה בה\u0004 כבר יבם אחד \u0003מאמר,\u0004 כלומר, שקידש אותה לו. ואף שאין תוקף גמור לקידושין אלה כמו לקידושין אחרים, ואין הדבר שולל לגמרי את האפשרות שהיבם האחר יפסול את הקידושין הללו — מכל מקום אסורה היא לאחרים ומשום כך הוא מפר את נדריה. \u0003ור' אליעזר סבר לה\u0004 \u0005[סבור]\u0006 \u0003כ\u0004דעת \u0003בית שמאי, דאמרי\u0004 \u0005[שאומרים]\u0006 : \u0003מאמר קונה קנין גמור\u0004 כמו קידושין.","\u0003ור' יהושע אומר לך: הני מילי\u0004 \u0005[דברים אלה]\u0006 אמורים \u0003בחד יבם\u0004 \u0005[ביבם אחד]\u0006, \u0003אבל בשני יבמין —\u0004 \u0003לא.\u0004 ומדוע? \u0003מי איכא מידי\u0004 \u0005[האם יש דבר]\u0006 כזה שאדם שקידושיו אינם גמורים עד כדי \u0003דכי אתי אחוהי\u0004 \u0005[שכאשר בא אחיו]\u0006 היבם האחר יכול \u0003אסר עליה\u0004 \u0005[לאסור עליו]\u0006 את האשה הזו \u0003בביאה\u0004 עליה, \u0003או בגיטא\u0004 \u0005[ב\u0006מתן \u0005גט]\u0006 \u0003ו\u0004בכל זאת \u0003מפר? ור' עקיבא סבר: אין זיקה\u0004 כלל, ושומרת יבם אינה נחשבת כקשורה קשר אישות אל היבם עד שישאנה.","ושואלים שוב על דעת ר' אליעזר: \u0003ול\u0004דעת \u0003ר' אלעזר,\u0004 ש\u0003אמר:\u0004 ש\u0003מאמר לבית שמאי אין קונה\u0004 קנין גמור, \u0003אלא\u0004 מועיל רק כדי \u0003לדחות בצרה.\u0004 שאם היתה לאח שמת אשה אחרת (שגם היא עומדת לייבום) ועשה מאמר בזו — בטלה זיקת הייבום מצרתה, והיא מותרת להינשא לכל אדם. אבל מלבד זאת אין למאמר תוקף כמו לקידושין, אם כן, \u0003מאי איכא למימר\u0004 \u0005[מה יש לומר]\u0006, איך יכול היבם, אף שעשה מאמר, להפר, לדעת ר' אליעזר?","ומשיבים: \u0003הכא במאי עסקינן\u0004 \u0005[כאן במה אנו עוסקים] —\u0006 \u0003כגון שעמד\u0004 אחד היבמים \u0003בדין,\u0004 שתבעתו האשה בבית דין שיישאנה, \u0003ואיתחייב\u0004 \u0005[והתחייב]\u0006 \u0003לה מזונות, ו\u0004כיון שהוא חייב במזונותיה הרי יש להסביר את הדברים \u0003כדרב פנחס משמיה\u0004 \u0005[משמו]\u0006 של \u0003רבא,\u0004 ש\u0003אמר:\u0004 \u0003כל הנודרת —\u0004 \u0003על דעת בעלה\u0004 המפרנס אותה, \u0003היא נודרת,\u0004 ומשום כך הוא מפר את נדריה."],["על האופן בו העמדנו את דברי ר' אליעזר מקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]\u0006 \u0003אמר ר' אליעזר: ומה אם אשה שקנה לעצמו הרי הוא מיפר\u0004 את \u0003נדריה, אשה שהקנו לו מן השמים —\u0004 \u0003אינו דין שמיפר נדריה? ואי\u0004 \u0005[ואם]\u0006 מדובר פה כפי שהסברנו \u0003בשעשה בה מאמר\u0004 (קידושי כסף), הלא אף זה \u0003קנה לעצמו הוא\u0004 שהרי הוא עצמו עשה בה מאמר! ומשיבים: מכל מקום מה \u0003שקנה לעצמו\u0004 הרי זה \u0003על ידי שמים\u0004 שהרי לא הוא שבחר בה, אלא משמים הקנו אותה לו.","ואומרים: אם כן \u0003תפשוט\u0004 \u0005[תפתור]\u0006 מכאן את מה \u0003דבעי\u0004 \u0005[ששאל]\u0006 \u0003רבה:\u0004 האם \u0003מאמר ל\u0004שיטת \u0003בית שמאי אירוסין\u0004 הוא \u0003עושה או נשואין\u0004 גמורים הוא \u0003עושה? תפשוט\u0004 \u0005[תפתור]\u0006 מדברי ר' אליעזר (ההולך לשיטתם) ש\u0003נשואין\u0004 הוא ש\u0003עושה. דאי\u0004 \u0005[שאם]\u0006 תאמר שהמאמר רק \u0003אירוסין עושה —\u0004 \u0003הא תנן\u0004 \u0005[הרי שנינו\u0006 במשנה\u0005]\u0006 : \u0003נערה המאורסה אביה ובעלה\u0004 (ארוסה) \u0003מפירין נדריה,\u0004 ואם כן היה צריך לומר שגם האב צריך להשתתף כדי להפר את נדרי בתו הזקוקה לייבום.","\u0003אמר רב נחמן בר יצחק:\u0004 אין מכאן כל ראיה כיון שאכן אפשר לומר כי \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"יפר\"\u0004 שנאמר כאן — \u0003יפר בשותפות\u0004 עם האב.","ומעירים: \u0003תניא נמי\u0004 \u0003הכי\u0004 \u0005[שנויה\u0006 ברייתא \u0005גם כן כך]\u0006 \u0003כר' אמי: שומרת יבם, בין\u0004 ל\u0003יבם אחד בין\u0004 ל\u0003שני יבמין, ר' אליעזר אומר: יפר\u0004 היבם, \u0003ור' יהושע אומר:\u0004 רק אם היתה שומרת יבם \u0003לאחד ולא לשנים. ר' עקיבא אומר: לא לאחד ולא לשנים.\u0004","\u0003אמר ר' אליעזר: ומה אם אשה שאין לו חלק בה עד שלא תבא לרשותו,\u0004 כלומר, סתם אשה, שאין לו כל קשר איתה לפני שמארס אותה, מכל מקום \u0003משבאת\u0004 (משבאה) \u0003לרשותו —\u0004 \u0003נגמרה לו\u0004 ומפר נדריה. \u0003אשה,\u0004 זו היבמה, \u0003שיש לו חלק עד שלא תבא לרשותו, משבאת לרשותו אינו דין שתגמור לו\u0004 לענין זה?","\u0003אמר לו ר' עקיבא: לא, אם אמרת באשה שקנה הוא לעצמו\u0004 בקידושין, \u0003שכשם שאין לו חלק בה\u0004 לפני כן, \u0003כך אין לאחרים חלק בה. תאמר באשה\u0004 יבמה \u0003שהקנו לו מן השמים, שכשם שיש לו עמה חלק —\u0004 \u0003כך יש לאחרים,\u0004 לשאר היבמים, \u0003חלק בה!\u0004","\u0003אמר לו ר' יהושע: עקיבא, דבריך\u0004 שיש בה חלק לאחרים — נכונים \u0003בשני יבמין, מה אתה משיב על יבם אחד? אמר לו\u0004 לר' יהושע: \u0003כלום חלקנו על יבם אחד ועל שני יבמין, בין שעשה בה מאמר בין שלא עשה בה מאמר\u0004 בכל ענין אחר? \u0003וכשאר דברים כן נדרים.\u0004","ומעירים: \u0003בלשון הזה אמר בן עזאי\u0004 כששמע את המשא והמתן הזה בין החכמים: \u0003חבל עליך בן עזאי שלא שימשת\u0004 כל הצורך \u0003את ר' עקיבא,\u0004 שכל כך גדולה חכמתו.","את הברייתא הזו הבאנו כראיה לדברי רבי אמי, ושואלים: \u0003מאי\u0004 \u0005[מהו]\u0006 שאמרנו שברייתא זו"],["\u0003תניא כוותיה\u0004 \u0005[שנויה כשיטתו]\u0006 של \u0003ר' אמי?\u0004 והרי אין הדבר מפורש בברייתא. ומשיבים: \u0003דקתני\u0004 \u0005[ששנה\u0006 שם\u0005]\u0006 בדברי ר' עקיבא: \u0003בין שעשה בה מאמר ובין שלא עשה בה מאמר.\u0004 משמע שדברי ר' אליעזר מתייחסים ליבמה שעשה בה מאמר.","\u0003אי נמי מרישא\u0004 \u0005[או גם כן מתחילתה\u0006 של הברייתא\u0005]\u0006 \u0003דקתני\u0004 \u0005[ששנה\u0006 בה\u0005]\u0006 : \u0003משנכנסה לרשותו נגמרה לו. ואי\u0004 \u0005[ואם]\u0006 מדובר פה במקרה ש\u0003לא קדיש\u0004 \u0005[קידש]\u0006 \u0003מאי\u0004 \u0005[מה]\u0006 לשון \u0003\"נגמרה לו\"? תפשוט מיניה\u0004 \u0005[תפתור ממנה]\u0006 שכאן מדובר ביבמה \u0003כשעשה בה מאמר.\u0004","ושואלים לעצם לשון הברייתא: \u0003מאי\u0004 \u0005[מה]\u0006 פירוש \u0003\"וכשאר דברים כן נדרים\" דקתני\u0004 \u0005[ששנה]\u0006 שם? מה הם אותם דברים? \u0003אמר רבא: הכי קתני\u0004 \u0005[כך שנה],\u0006 כך משמעות הדברים: וכי \u0003אי\u0004 \u0005[אין]\u0006 \u0003אתה מודה שאין חייבין סקילה\u0004 אם בא אדם אחר על יבמה, כפי שמתחייב מי שבא על \u0003נערה המאורסה?\u0004 ואם כן אף בנדרים אין דין ארוסה ויבמה שווה.","\u0003אמר רב אשי: מתניתין נמי דיקא\u0004 \u0005[משנתנו גם כן מדוייקת]\u0006 אם מדקדקים בלשונה, שאף בה נאמרה סברה זו. ששנינו בה: \u0003אין יבמה גמורה לאישה כשם שארוסה גמורה לאישה.\u0004","\u0003האומר לאשתו \"כל הנדרים שתדורי מכאן\u0004 (מעכשיו) \u0003עד שאבא ממקום פלוני הרי הן קיימין\" —\u0004 \u0003לא אמר כלום.\u0004 אמר לה \"כל הנדרים שתדורי עד שאבוא ממקום פלוני \u0003הרי הן מופרין\" ר' אליעזר אמר: מופר, וחכמים אומרים: אינו מופר. אמר ר' אליעזר\u0004 בהסבר שיטתו: \u0003אם הפר נדרים שבאו לכלל איסור,\u0004 כלומר, נדרים שכבר נדרה ואסורה בהם — \u0003לא יפר נדרים שלא באו לכלל איסור?\u0004","\u0003אמרו לו\u0004 חכמים בתשובה: \u0003הרי הוא אומר \"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד) ללמד: \u0003את שבא לכלל הקם,\u0004 נדר כזה שאפשר להקים אותו, כלומר, נדר שנדרה כבר — הוא זה ש\u0003בא לכלל הפר,\u0004 אבל נדר ש\u0003לא בא לכלל הקם —\u0004 \u0003לא בא\u0004 גם \u0003לכלל הפר.\u0004","\u0003איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 : \u0003ל\u0004דעת \u0003ר' אליעזר,\u0004 האם נדרים אלה שהוא מפר מראש \u0003מיחל חלין\u0004 \u0005[חלים]\u0006 הם לרגע אחד \u0003ו\u0004אולם \u0003בטלין\u0004 \u0005[בטלים]\u0006 מיד לאחר מכן, \u0003או דלמא\u0004 \u0005[שמא]\u0006 \u0003לא חלין\u0004 הם \u0003כלל?\u0004 שכיון שהפירם לפני שנדרה אין להם תחולה כלל. ומסבירים: \u0003למאי נפקא מינה\u0004 \u0005[מה יוצא מזה]\u0006 למעשה, מה ההבדל אם הם חלים ובטלים או שאינם חלים כלל, שהרי בפועל אין להם כל קיום —"],["\u0003כגון דאתפיס אחרינא בהדין נדרא\u0004 \u0005[שהתפיס אחר בנדר זה],\u0006 ששמע אדם אחר את נדרה, ואמר שהוא נודר כמותה. ומעתה תלוי הדבר בשאלתנו, שכן \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שנדרים אלה \u0003חלין —\u0004 \u0003הויא תפיסותא\u0004 \u0005[הריהי התפסה]\u0006 בעלת תוקף ונדרו של אותו אדם נתפס ברגע שחל בו הנדר, ואף שנדרה של האשה מופר לאחר מכן, נדרו שלו קיים. ואולם \u0003אי אמרת\u0004 \u0005[אם אומר אתה]\u0006 שנדרים אלה \u0003לא חלין —\u0004 \u0003לא איכא מששא\u0004 \u0005[אין כאן ממש]\u0006 בנדרו של האחר, כיון שלא היה לו במה להיתפס.","ואם כן \u0003מאי\u0004 \u0005[מה]\u0006 הדין? ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו במשנה, \u0003אמר ר' אליעזר: אם הפר נדרים שבאו לכלל איסור, לא יפר נדרים שלא באו לכלל איסור? שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003לא חלין\u0004 הם כלל, שהרי אמר \"שלא באו לכלל איסור\"!","ודוחים: \u0003מי קתני\u0004 \u0005[האם שנה]\u0006 \u0003\"שאינן באין\u0004 לכלל איסור \u0003\"?\u0004 \u0003\"שלא באו\" קתני\u0004 \u0005[שנה],\u0006 כלומר, בשעה שהפר \u0003עדיין לא באו\u0004 אבל כשתידור — הם באים לרגע לכלל איסור.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא, \u0003אמר להן ר' אליעזר: ומה במקום שאין מיפר נדרי עצמו משנדר\u0004 (לאחר שנדר), שאין אדם יכול להתיר נדרי עצמו, מכל מקום \u0003מיפר נדרי עצמו עד שלא ידור,\u0004 שיכול להתנות מראש שהנדרים שידור לא יהיו קיימים. \u0003מקום שמפר נדרי אשתו\u0004 אפילו \u0003משתדור\u0004 (לאחר שנדרה) וחל נדרה, \u0003אינו דין שיפר נדרי אשתו עד שלא תדור?\u0004","ונדייק מתוך השוואת הדברים: \u0003מאי לאו\u0004 \u0005[האם אין]\u0006 נדריה של \u0003אשתו דומיא דיליה\u0004 \u0005[בדומה\u0006 לנדרים \u0005שלו]\u0006, \u0003מה [הוא]\u0004 כשמבטל מראש ש\u0003לא חיילין\u0004 \u0005[חלים]\u0006 כלל, \u0003אף\u0004 נדרי \u0003אשתו נמי\u0004 \u0005[גם כן]\u0006 מדובר ש\u0003לא חיילין\u0004 \u0005[חלים]\u0006? ודוחים: \u0003לא,\u0004 אין להוכיח מכאן, אפשר לומר \u0003הא כדאיתא והא כדאיתא\u0004 \u0005[זה כמו שהוא וזה כמו שהוא],\u0006 שלענין קל וחומר הרי היתה זו השוואה מספקת, אבל אין להוכיח מכאן ששני המקרים שווים בכל פרטיהם.","\u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו בברייתא, \u0003אמרו לו לר' אליעזר:\u0004 קל וחומר זה אינו נכון, שכן אפשר להוכיח שאי אפשר להשתמש בו במקומות אחרים. והוכחה לדבר: \u0003ומה מקוה שמעלה\u0004 (מטהר) \u0003את הטמאין מטומאתן\u0004 כשטובלים בו, בכל זאת \u0003אין מציל על הטהורים מליטמא,\u0004 שאם טובל אדם במקוה — איננו ניצול על ידי כך מלהיטמא אחר כך אם ייגע בטומאה. \u0003אדם שאין מעלה את הטמאין מטומאתן,\u0004 שאם בלע כלי (כגון טבעת) טמא וטבל — נשאר הכלי בטומאתו, \u0003אינו דין הוא שלא יציל על הטהורין מליטמא,\u0004 שאם בלע כלי טהור, ונטמא האיש — שיטמא גם הכלי שבתוכו? והרי אין הדבר כן, שהרי הבלוע בו אינו מטמא. ואם כן, אין מקום ללמוד בקל וחומר מדבר שחל כבר לדבר שעדיין לא חל, ולהיפך.","ולענין הבעיה שעסקנו בה האם הנדרים חלים בכלל, \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שלדעתו של ר' אליעזר הנדרים הללו \u0003לא חיילין\u0004 \u0005[חלים]\u0006 כלל, שהרי טענו כנגדו מדין טומאה, שלא תחול כל עיקר (\"על הטהורין מליטמא\")!"],["\u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של ברייתא זו: \u0003אמרו לו לר' אליעזר: אם מטבילין כלי טמא ליטהר\u0004 מטומאתו, \u0003יטבילו כלי\u0004 קודם לכך \u0003לכשיטמא ליטהר? שמע מינה\u0004 \u0005[למד מכאן]\u0006 לענייננו כי אף לדעת ר' אליעזר הנדרים הללו \u0003חיילין\u0004 \u0005[חלים]\u0006 ומופרים מיד, שהרי חכמים מקשים עליו מדין כלי שייטמא וייטהר מיד לאחר מכן.","\u0003אמרי\u0004 \u0005[אומרים]\u0006 בתשובה לכך: \u0003רבנן\u0004 \u0005[חכמים]\u0006 \u0003לא קיימי\u0004 \u0005[עמדו],\u0006 לא נתברר \u0003להון בטעמיה\u0004 \u0005[להם בטעמו]\u0006 של \u0003ר' אליעזר,\u0004 שלא ידעו מה בדיוק הוא סבור, \u0003והכי קאמרי ליה\u0004 \u0005[וכך אומרים הם לו]\u0006 : \u0003מאי סבירא לך\u0004 \u0005[מה סבור אתה]\u0006? \u0003אי סבירא לך דחיילין\u0004 \u0005[אם סבור אתה ש\u0006הנדרים \u0005חלים]\u0006 \u0003ובטלין\u0004 \u0005[ובטלים] —\u0006 \u0003תהוי\u0004 \u0005[תהיה]\u0006 הדוגמה של \u0003כלי תיובתך\u0004 \u0005[קושיה עליך]\u0006, \u0003אי לא סבירא לך דחיילין\u0004 \u0005[אם אין אתה סבור ש\u0006הם \u0005חלים]\u0006 אלא אתה חושב שהם בטלים מעיקרם — \u0003תהוי\u0004 \u0005[תהיה]\u0006 הדוגמה של \u0003מקוה תיובתך\u0004 \u0005[קושייתך].\u0006","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ששנינו עוד בענין חילופי הדברים בין החכמים, \u0003אמר להם ר' אליעזר: ומה זרעים טמאים, כיון שזרען בקרקע\u0004 נעשו \u0003טהורין, זרועין ועומדים\u0004 שנגעה בהם טומאה — \u0003לא כל שכן\u0004 שלא ייטמאו? ולענייננו \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 שסבור ר' אליעזר כי הנדרים שמפר הבעל מראש \u0003לא חיילין\u0004 \u0005[חלים]\u0006 כלל, כדרך שהזרועים ועומדים אינם נטמאים כלל.","ולעצם המחלוקת בין ר' אליעזר וחכמים, שואלים: \u0003ורבנן לא דרשי\u0004 \u0005[ו\u0006כי \u0005חכמים אינם דורשים]\u0006 \u0003קל וחומר\u0004 באופן זה, שאם דבר מתבטל על ידי מעשה כלשהו, יפה כוחו של מעשה זה לגרום שלא יתרחש הדבר מעיקרו? \u0003והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 : \u0003יכול ימכור אדם את בתו\u0004 לאמה \u0003כשהיא נערה? אמרת\u0004 (אומר אתה) \u0003קל וחומר\u0004 יש בדבר: אם האמה כשהיא \u0003מכורה כבר\u0004 בהיותה קטנה, \u0003יוצאה\u0004 כשנעשית נערה, זו ש\u0003אינה מכורה —\u0004 \u0003אינו דין שלא תימכר\u0004 כאשר נעשית נערה? משמע שגם חכמים לומדים קל וחומר באותה דרך!"],["\u0003אין\u0004 \u0005[כן]\u0006, \u0003בעלמא דרשי\u0004 \u0005[בכלל דורשים]\u0006 הם \u0003קל וחומר\u0004 בדרך זו, \u0003ושאני הכא\u0004 \u0005[ושונה כאן]\u0006 ש\u0003אמר קרא\u0004 \u0005[הכתוב]\u0006 כגזירה \u0003\"אישה יקימנו ואישה יפרנו\"\u0004 (במדבר ל, יד), לומר: \u0003את שבא לכלל הקם —\u0004 \u0003בא לכלל הפר, את שלא בא לכלל הקם —\u0004 \u0003לא בא לכלל הפר.\u0004","\u0003הפרת נדרים\u0004 יכולה להיעשות על ידי האב או הבעל \u0003כל\u0004 אותו \u0003היום\u0004 שבו נדרה, עד סופו. \u0003יש בדבר להקל\u0004 (להאריך את זמן אפשרות ההפרה) \u0003ולהחמיר\u0004 (לקצר את הזמן);","\u0003כיצד?\u0004 אם \u0003נדרה בלילי שבת\u0004 הרי כל יום השבת הוא זמן להפרת נדר זה, ואם רוצה \u0003יפר בלילי שבת, וביום השבת, עד שתחשך.\u0004 ומצד שני, אם \u0003נדרה עם חשכה,\u0004 כלומר, סמוך לחשיכה — \u0003מפר עד שלא תחשך, שאם חשכה ולא הפר —\u0004 שוב \u0003אינו יכול להפר,\u0004 שהרי זה נחשב כיום המחרת \u0003.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003הפרת נדרים\u0004 יכולה להיעשות \u0003כל היום\u0004 בו נדרה בלבד. \u0003ר' יוסי בר' יהודה ור' אלעזר בר' שמעון אמרו:\u0004 זמן הפרת נדרים \u0003מעת לעת\u0004 (עשרים וארבע שעות) מאז שמע את הנדר. שואלים: \u0003מאי טעמא\u0004 \u0005[מהו הטעם]\u0006 של ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006? ומשיבים: \u0003אמר קרא\u0004 \u0005[הכתוב]:\u0006 \u0003\"\u0004ואם הפר יפר אותם אישה \u0003ביום שמעו\"\u0004 (במדבר ל, יג), לומר: דווקא באותו יום ששומע, שאינו מפר אלא עד סוף אותו היום.","ושואלים: \u0003ורבנן מאי טעמייהו\u0004 \u0005[ו\u0006שני \u0005חכמים\u0006 אלה, ר' יוסי בר' יהודה ור' אלעזר בר' שמעון, \u0005מה טעמם] —\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"מיום אל יום\"\u0004 (במדבר ל, טו). שמכאן מובן שיכול להפר את הנדר משעה פלונית ביום זה עד אותה שעה ביום הבא.","ושואלים: \u0003ול\u0004דעת ה\u0003תנא קמא\u0004 \u0005[הראשון]\u0006 \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"מיום אל יום\"!\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר להיאמר. \u0003דאי\u0004 \u0005[שאם]\u0006 היה כתוב רק \u0003\"ביום שמעו\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 \u0003ביממא\u0004 \u0005[ביום] —\u0006 \u0003אין\u0004 \u0005[כן]\u0006 יפר, \u0003בליליא\u0004 \u0005[בלילה] —\u0006 \u0003לא,\u0004 לכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"מיום אל יום\",\u0004 ללמד שהדבר ניתן להיעשות אף בשעות שבין יום זה ליום אחר, דהיינו בלילה.","ושואלים מצד שני: \u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003\"מיום אל יום\"\u0004 דווקא, וכוונתו מעת לעת, \u0003הא כתיב\u0004 \u0005[הרי נאמר]\u0006 \u0003\"ביום שמעו\"!\u0004 ומשיבים: \u0003איצטריך\u0004 \u0005[הוצרך]\u0006 הדבר, \u0003דאי כתיב\u0004 \u0005[שאם היה נאמר]\u0006 רק \u0003\"מיום אל יום\" הוה אמינא\u0004 \u0005[הייתי אומר]\u0006 כי \u0003מחד בשבא לחד בשבא ליפר\u0004 \u0005[מ\u0006יום \u0005ראשון בשבת,\u0006 בשבוע, \u0005ל\u0006יום \u0005ראשון בשבת\u0006 שלאחר מכן \u0005שיפר]\u0006 \u0003לה,\u0004 כלומר, מאותו יום עד לאותו יום בשבוע הבא, לכן \u0003כתיב\u0004 \u0005[נאמר]\u0006 \u0003\"ביום שמעו\"\u0004 לומר שהדבר מוגבל ליום אחד בלבד.","\u0003אמר ר' שמעון בן פזי אמר ר' יהושע בן לוי: אין הלכה כאותו הזוג,\u0004 ר' יוסי בר' יהודה ור' אלעזר בר' שמעון, שמפר מעת לעת, אלא באותו יום בלבד, כמשנתנו. מסופר: \u0003לוי סבר למיעבד כהני תנאי\u0004 \u0005[חשב לעשות כאותם\u0006 שני \u0005התנאים].\u0006 \u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רב: הכי\u0004 \u0005[כך]\u0006 \u0003אמר חביבי\u0004 \u0005[דודי,\u0006 ר' חייא\u0005]\u0006 : \u0003אין הלכה כאותו הזוג.\u0004","מסופר, כי בהתרת נדרים \u0003חייא בר\u0004 (בנו של) \u0003רב שדי גירא ובדיק\u0004 \u0005[\u0006היה \u0005יורה חץ ובודק]\u0006 באותה שעה את הנדר להתירו, שלא היה מקדיש לכך זמן רב ותשומת לב, אלא מיד מתיר. וכן \u0003רבה בר רב הונא יתיב וקאים\u0004 \u0005[\u0006היה \u0005יושב ועומד]\u0006 ולא היה מדקדק בדבר, ומיד היה מתיר."],["\u0003תנן התם\u0004 \u0005[שנינו\u0006 במשנה \u0005שם]\u0006 במסכת שבת: אב או בעל \u0003מפירין נדרים בשבת, ונשאלין\u0004 לחכם להתיר \u0003לנדרים שהן לצורך השבת. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 : האם מה שנאמר \"לצורך השבת\" מתייחס לשתי ההלכות, לומר כי אף \u0003מפירין נדרים בשבת\u0004 דווקא כאשר הם \u0003לצורך השבת, או דלמא\u0004 \u0005[שמא]\u0006 הדבר מתייחס רק להתרת חכם אבל הפרה בשבת נעשית \u0003אפילו שלא לצורך\u0004 השבת?","ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לשאלה ממה \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב זוטי דבי\u0004 \u0005[מבית\u0006 מדרשו\u0005]\u0006 של \u0003רב פפי\u0004 ברייתא זו: \u0003אין מפירין נדרים אלא לצורך השבת. אמר רב אשי: הא\u0004 \u0005[הרי]\u0006 \u0003לא תנן הכי\u0004 \u0005[שנינו כך\u0006 במשנה\u0005]\u0006, ששנינו: \u0003נדרה עם חשיכה —\u0004 \u0003מפר לה עד שלא תחשך,\u0004 ואם חשכה ולא הפר שוב אינו יכול להפר. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 כי \u0003לצורך השבת —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 מפר, \u0003שלא לצורך השבת —\u0004 \u0003לא\u0004 יפר, \u0003מאי איריא\u0004 \u0005[מה שייך]\u0006 מדוע שנה שדווקא מש \u0003חשכה\u0004 אינו יכול להפר? והרי \u0003אפילו בתוך היום אינו יכול להפר\u0004 נדרים שהם \u0003שלא לצורך\u0004 השבת!","ומשיבים: מחלוקת \u0003תנאי\u0004 \u0005[תנאים]\u0006 \u0003היא\u0004 בהפרה בשבת שלא לצורך השבת, ששנינו: \u0003הפרת נדרים כל היום, ר' יוסי בר' יהודה ור' אלעזר בר' שמעון אמרו: מעת לעת.\u0004","\u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 \u0003כל היום —\u0004 \u0003אין\u0004 \u0005[כן]\u0006, \u0003טפי\u0004 \u0005[יותר\u0006 מזה\u0005]\u0006 — \u0003לא, אפילו\u0004 נדרים \u0003שלא לצורך השבת\u0004 הריהו \u0003מפר,\u0004 שהרי אינו יכול להפר נדרים אלה גם אחר השבת.\u0003 למאן דאמר מעת לעת לצורך השבת אין שלא לצורך השבת לא.\u0004","בהמשכה של אותה משנה במסכת שבת שנינו: \u0003ונשאלין לנדרים שהן לצורך השבת. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]\u0006 : האם מדובר דווקא \u0003כשלא היה להם\u0004 לשואלים \u0003פנאי\u0004 להישאל על נדרים אלה לפני השבת, \u0003או דלמא\u0004 \u0005[שמא]\u0006 אפילו \u0003כשהיה להם פנאי?\u0004 ומשיבים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה \u0003דאיזדקיקו ליה רבנן\u0004 \u0005[שנזקקו לו חכמים]\u0006 \u0003לבריה\u0004 \u0005[לבנו]\u0006 של \u0003רב זוטרא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב זעירא\u0004 להתיר נדר בשבת \u0003אפילו בנדרים שהיה להם פנאי\u0004 להישאל עליהם \u0003מבעוד יום.\u0004","ועוד בענין נדרים בשבת, \u0003סבר רב יוסף למימר\u0004 \u0005[לומר]\u0006 : מה שאמרו כי \u0003נשאלין\u0004 לחכם על \u0003נדרים בשבת, ב\u0004פני \u0003יחיד מומחה —\u0004 \u0003אין\u0004 \u0005[כן]\u0006 הותר הדבר, אבל להתיר \u0003בשלשה הדיוטות —\u0004 \u0003לא\u0004 הותר בשבת, \u0003משום דמתחזי כדינא\u0004 \u0005[שנראה\u0006 הדבר \u0005כדין]\u0006 שאוספים שלושה אנשים לדון בדבר, ואין דנים בשבת.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי: כיון דסבירא לן\u0004 \u0005[שסבורים אנו]\u0006 ופוסקים שמתירים נדרים \u0003אפילו מעומד,\u0004 ו\u0003אפילו\u0004 אם היו המתירים \u0003קרובים\u0004 הפסולים לדון אותו אדם, \u0003ו\u0004מתירים נדרים \u0003אפילו בלילה\u0004 שאין דנים בו — אם כן \u0003לא מתחזי כדינא\u0004 \u0005[אין\u0006 הדבר \u0005נראה\u0006 עוד \u0005כדין]\u0006 לפי שאין דנים אלא מיושב, ובכשרים, וביום, ולכן אפשר להתיר בשבת אפילו בפני שלושה הדיוטות.","\u0003אמר ר' אבא אמר רב הונא אמר רב: הלכה\u0004 היא ש\u0003מפירין נדרים בלילה.\u0004 ותוהים: מה צורך להשמיע הלכה זו? \u0003והא מתניתין\u0004 \u0005[והרי משנתנו]\u0006 \u0003היא: נדרה בלילי שבת\u0004 יפר בלילי שבת! \u0003אלא אימא\u0004 \u0005[אמור]\u0006 שכך היתה הלכתו של רב: \u0003הלכה, נשאלין\u0004 לחכם להתיר נדר \u0003בלילה.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003ר' אבא לרב הונא:\u0004 האם \u0003אמר רב הכי\u0004 \u0005[כך]\u0006? \u0003אמר ליה\u0004 \u0005[לו]\u0006 : \u0003אישתיק\u0004 \u0005[שתק]\u0006 רב בשעה שנאמרה לפניו הלכה זו. \u0003אמר ליה\u0004 \u0005[לו]\u0006 ר' אבא שוב, שלא היה בטוח ששמע היטב את הדבר: האם \u0003אישתיק קא אמרת\u0004 \u0005[שתק אמרת]\u0006 וכיון שלא דחה את הדבר משמע שאף הוא סבור שכך ההלכה, \u0003או שתי קאמרת\u0004 \u0005[שתה אמרת]\u0006, כלומר שהיה שותה באותה שעה, ולא נפנה לעסוק בדבר, ושתיקתו אין משמעה שהוא מסכים?","כדי לברר את דעתו של רב בענין זה, מביאים מה ש\u0003אמר רב איקא בר אבין: איזדקיק ליה\u0004 \u0005[נזקק לו]\u0006 \u0003רב לרבה\u0004 להתיר לו נדר"],["והיה זה \u0003בקיטונא דבי רב\u0004 \u0005[בחדר בית המדרש]\u0006 כשהיה \u0003עומד,\u0004 והיה \u0003יחידי ו\u0004היה זה \u0003בלילה.\u0004","\u0003אמר רבה אמר רב נחמן: הלכה, נשאלין\u0004 להתיר \u0003נדרים\u0004 כשהוא \u0003עומד, יחידי, ובלילה, ובשבת, ובקרובים, ואפילו היה להן פנאי מבעוד יום.\u0004","על כך שואלים: \u0003עומד? והתניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]\u0006 : \u0003ירד רבן גמליאל מן החמור ונתעטף וישב והתיר לו נדרו.\u0004 ומדוע ישב? ומשיבים, \u0003רבן גמליאל סבר: פותחין בחרטה.\u0004 כלומר, אין מתירים סתם, אלא יש צורך לחפש פתח להתיר ולמצוא אופן של חרטה על הנדר מתחילתו, \u0003מיעקר נדרא בעינן\u0004 \u0005[לעקור\u0006 את \u0005הנדר אנו צריכים]\u0006 \u0003ו\u0004משום כך \u0003בעי עיוני\u0004 \u0005[צריך לעיין\u0006 בדבר\u0005]\u0006, \u0003אהכי\u0004 \u0005[משום כך]\u0006 \u0003ישב. ו\u0004אילו \u0003רב נחמן סבר: אין פותחין בחרטה\u0004 שאין צורך לחפש פתח כזה, \u0003ו\u0004לכן יכול להתיר את הנדר \u0003אפילו\u0004 כשהוא \u0003מעומד.\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבא לרב נחמן: חזי מר\u0004 \u0005[יראה אדוני]\u0006 \u0003האי מרבנן דאתא ממערבא\u0004 \u0005[אחד החכמים שבא מארץ ישראל]\u0006 \u0003ואמר: איזדקיקו ליה רבנן\u0004 \u0005[נזקקו לו חכמים]\u0006 להתיר נדר \u0003לבריה\u0004 \u0005[לבנו]\u0006 של \u0003רב הונא בר אבין, ושרו ליה נדריה\u0004 \u0005[והתירו לו\u0006 את \u0005נדרו]\u0006 \u0003ואמרו ליה\u0004 \u0005[לו]\u0006 : \u0003זיל ובעי רחמי\u0004 \u0005[לך ובקש רחמים]\u0006 \u0003על נפשך\u0004 \u0005[עצמך]\u0006 ש\u0003חטאת\u0004 במה שנדרת. \u0003דתני\u0004 \u0005[ששנה]\u0006 \u0003רב דימי אחוה\u0004 \u0005[אחיו]\u0006 של \u0003רב ספרא: כל הנודר, אף על פי שהוא מקיימו\u0004 לנדר — \u0003נקרא חוטא. אמר רב זביד: מאי קרא\u0004 \u0005[מהו הכתוב]\u0006 המלמד על כך — \u0003\"וכי תחדל לנדר לא יהיה בך חטא\"\u0004 (דברים כג, כג), \u0003הא\u0004 \u0005[הרי]\u0006 אם \u0003לא חדלת\u0004 ונדרת — \u0003איכא\u0004 \u0005[יש]\u0006 בזה \u0003חטא.\u0004","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005]\u0006 : \u0003האומר לאשתו \"כל נדרים שתדורי אי אפשי\u0004 (אין רצוני) \u0003שתדורי\"\u0004 או אמר לה \u0003\"אין זה נדר\" —\u0004 \u0003לא\u0004 \u0003אמר כלום\u0004 שאין זה נוסח של הפרה. ולענין קיום אם אמר לה \u0003\"יפה עשית\"\u0004 או \u0003\"אין כמותך\"\u0004 או \u0003\"אם לא נדרת מדירך אני\" —\u0004 \u0003דבריו קיימין\u0004 והרי זה קיומו של הנדר.","\u0003לא יאמר אדם לאשתו בשבת\u0004 כשהוא מפר את נדרה \u0003\"מופר ליכי\u0004 \u0005[לך]\u0006 \u0003\"\u0004או \u0003\"בטיל ליכי\u0004 \u0005[לך]\u0006 \u0003\" כדרך שאומר לה בחול, אלא אומר לה\u0004 אם נדרה ממאכל ומשתה \u0003\"טלי ואכלי\" \"טלי ושתי\", והנדר בטל מאליו. אמר ר' יוחנן: וצריך\u0004 בכל זאת \u0003שיבטל בלבו\u0004 את הנדר, ולא די כשאומר לה לאכול או לשתות.","\u0003תניא\u0004 \u0005[שנויה\u0006 ברייתא\u0005],\u0006 \u0003בית שמאי אומרים: בשבת מבטל\u0004 את הנדר \u0003בלבו, בחול מוציא בשפתיו\u0004 את ביטולו של הנדר. \u0003ובית הלל אומרים: אחד זה ואחד זה\u0004 בין בשבת ובין בחול, דיו שיהיה \u0003מבטל בלבו, ואין צריך להוציא בשפתיו.\u0004","\u0003אמר ר' יוחנן: חכם שאמר בלשון בעל,\u0004 שאמר שהוא מפר את הנדר, \u0003ובעל שאמר בלשון חכם\u0004 שהוא מתיר את הנדר — \u0003לא אמר כלום,\u0004 שכל אחד מהם יש לו ייפוי כוח לבטל הנדר באופן זה דווקא, ולא באופן אחר.","\u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]\u0006 באותו ענין, שעל הכתוב הפותח פרשת נדרים \u0003\"זה הדבר\u0004 אשר צוה ה'\u0003\"\u0004 (במדבר ל, ב) אמרו חכמים: מן ההדגשה \"זה\" למדים כי \u0003החכם מתיר\u0004 את הנדר \u0003ואין בעל מתיר. שיכול\u0004 הייתי לומר: \u0003ומה חכם שאין מפר\u0004 נדר — בכל זאת \u0003מתיר\u0004 אותו, \u0003בעל שמפר\u0004 נדר \u0003אינו דין שמתיר? תלמוד לומר:\u0004"],["\u0003\"זה הדבר\",\u0004 לומר, בדיוק כפי שנאמר בכתוב: \u0003חכם מתיר, ואין בעל מתיר. תניא אידך\u0004 \u0005[שנויה\u0006 ברייתא \u0005אחרת]\u0006 : מה שנאמר \u0003\"זה הדבר\"\u0004 בא ללמד ש\u0003בעל מפר ואין חכם מפר. שיכול\u0004 הייתי לומר: \u0003ומה בעל שאין מתיר\u0004 נדר — בכל זאת \u0003מפר\u0004 אותו, \u0003חכם שמתיר\u0004 נדר \u0003אינו דין ש\u0004אף \u0003מפר? תלמוד לומר: \"זה הדבר\" —\u0004 \u0003בעל מפר ואין חכם מפר.\u0004","ועוד שנינו במדרש ההלכה: \u0003נאמר כאן\u0004 בענין נדרים \u0003\"זה הדבר\", ונאמר להלן \"זה הדבר\" בשחוטי חוץ,\u0004 באיסור לשחוט קרבנות מחוץ למקדש (ויקרא יז, ב). \u0003מה בשחוטי חוץ\u0004 מפורש שנאמר הדבר אל \u0003אהרן ובניו וכל ישראל\u0004 (כאמור שם \"דבר אל אהרן ואל בניו ואל כל בני ישראל\") — \u0003אף פרשת נדרים אהרן ובניו וכל ישראל. ומה כאן\u0004 בפרשת נדרים (במדבר ל, ב), נאמרה הפרשה אל \u0003ראשי המטות\u0004 (\"וידבר משה אל ראשי המטות לבני ישראל\") — \u0003אף להלן\u0004 נאמר הדבר ל\u0003ראשי המטות.\u0004","ושואלים: \u0003בפרשת נדרים למאי הלכתא\u0004 \u0005[למה\u0006 באה \u0005ההלכה]\u0006 בגזירה השווה שהיא בכל ישראל? \u0003אמר רב אחא בר יעקב: להכשיר שלשה הדיוטות,\u0004 שאין צורך בראשי המטות — גדולי ישראל וחכמיהם, דווקא. ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003\"ראשי המטות\" כתיב\u0004 \u0005[נאמר]\u0006 שם במפורש! \u0003אמר רב חסדא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 שאמר זאת \u0003ר' יוחנן:\u0004 מה שנאמר \"ראשי המטות\" בנדרים הוא ללמד אפשרות של התרת נדרים גם \u0003ביחיד מומחה,\u0004 שמתיר את הנדר ואין צריך לכך בבית דין.","ושואלים: \u0003ראשי המטות בשחוטי חוץ למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 הוצרכו? \u0003אמר רב ששת: לומר שיש שאלה בהקדש,\u0004 שכשם שיכול הנודר נדר להישאל לחכם (או לבית דין של שלושה הדיוטות) ולהתיר נדרו — כך יכול גם המקדיש להישאל ולהתיר הקדש שהקדיש.","ושואלים: \u0003ל\u0004דעת \u0003בית שמאי\u0004 ש\u0003אמר\u0004 ש\u0003אין שאלה בהקדש,\u0004 הביטוי \u0003\"ראשי המטות\" דכתיב\u0004 \u0005[שנאמר]\u0006 \u0003בשחוטי חוץ למאי הלכתא\u0004 \u0005[למה,\u0006 לאיזו \u0005הלכה]\u0006 נאמר? ומשיבים: \u0003בית שמאי לית להו\u0004 \u0005[אין להם,\u0006 אינם מקבלים\u0005]\u0006 \u0003גזירה שוה\u0004 זו.","ושואלים: הואיל ואין בית שמאי דורשים גזירה שווה זו — \u0003\"זה הדבר\"\u0004 האמור \u0003בפרשת נדרים למאי כתיב\u0004 \u0005[למה,\u0006 לאיזה ענין \u0005נאמר]\u0006? ומשיבים: \u0003לומר\u0004 שיש לנהוג כפי שנאמר בדיוק: \u0003חכם מתיר ואין בעל מתיר,\u0004 ומצד שני — \u0003בעל מפר ואין חכם מפר.\u0004","ועוד שואלים: \u0003\"זה הדבר\"\u0004 שנאמר \u0003בשחוטי חוץ למאי כתיב\u0004 \u0005[למה נכתב]\u0006? ומשיבים: \u0003לומר: על השחיטה\u0004 בחוץ \u0003חייב, ואין חייב על המליקה\u0004 בחוץ, שאף שבמקדש קרבנות העוף נמלקים דווקא, אם מלק מחוץ למקדש — אינו עובר משום \"שחוטי חוץ\".","ושואלים: \u0003אלא לבית שמאי\u0004 אם אינם לומדים גזירה שווה בין פרשת נדרים ושחוטי חוץ, דין זה \u0003להכשיר שלשה הדיוטות\u0004 בהתרת נדרים \u0003מנלן\u0004 \u0005[מניין לנו]\u0006? ומשיבים: \u0003נפקא להו\u0004 \u0005[יוצא,\u0006 נלמד \u0005להם]\u0006 הדבר \u0003מ\u0004מה שפירשו ל\u0003רב אסי בר נתן.\u0004","\u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"וידבר משה את מעדי ה' אל בני ישראל\"\u0004 (ויקרא כג, מד) \u0003והתניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005],\u0006 \u0003ר' יוסי הגלילי אומר: \"מועדי\" נאמרו, ולא נאמרה שבת בראשית עמהן. בן עזאי אומר: \"מועדי\" נאמרו ולא נאמר פרשת נדרים עמהן.\u0004 עד כאן לשון הברייתא.","ומסופר: \u0003רב אסי בר נתן קשיא ליה הא מתניתא\u0004 \u0005[\u0006היתה \u0005קשה לו ברייתא זו].\u0006 \u0003אתא\u0004 \u0005[בא]\u0006 \u0003לנהרדעא לקמיה\u0004 \u0005[לפני]\u0006 \u0003רב ששת ולא אשכחיה\u0004 \u0005[מצאו]\u0006 שם, \u0003אתא אבתריה\u0004 \u0005[בא אחריו]\u0006 \u0003למחוזא\u0004 כדי לשאול דבר זה. \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב אסי בר נתן: האם אפשר לומר כי \u0003מועדי ה' נאמרו, ולא נאמרה שבת בראשית עמהן?\u0004","\u0003והא כתיב\u0004 \u0005[והרי נאמר]\u0006 \u0003שבת עמהן\u0004 באותה פרשה עצמה (הן בויקרא פרק כג, והן בבמדבר פרק כח)! \u0003ותו\u0004 \u0005[ועוד]\u0006 : איך אפשר לומר \u0003מועדי ה' נאמרו ולא נאמרה פרשת נדרים עמהן? והא מסיטרא כתיבא\u0004 \u0005[והרי בצד\u0006 היא \u0005כתובה],\u0006 מיד אחרי פרשת המועדות שבספר במדבר (פרק כח)! \u0003אמר ליה\u0004 \u0005[לו]\u0006 רב ששת: \u0003הכי קתני\u0004 \u0005[כך שנה],\u0006 כך יש להבין את הדברים:"],["\u0003מועדי ה' צריכין קידוש בית דין,\u0004 שזמני המועדים נקבעים רק על פי בית דין המקדשים את החודש, \u0003שבת בראשית אין צריכה קידוש בית דין,\u0004 שקדושתה חלה מעצמה, ואין צורך בהחלטת בית הדין לשם כך, וזו כוונת מה שאמרו שלא נאמרה שבת עם שאר המועדים.","וכך יש להבין גם את דברי בן עזאי: \u0003מועדי ה' צריכין מומחה,\u0004 שאין קביעת המועדים אלא על פי בית דין מומחים, \u0003ואין פרשת נדרים צריכין מומחה\u0004 אלא \u0003אפילו בית דין\u0004 של \u0003הדיוטות\u0004 יכולים להתיר נדרים.","ומקשים: \u0003והא\u0004 \u0005[והרי]\u0006 \u0003בפרשת נדרים \"ראשי המטות\" כתיב\u0004 \u0005[נאמר]\u0006 (במדבר ל, ב), ואיך אפשר לומר שיעשו זאת הדיוטות? \u0003אמר רב חסדא ואיתימא\u0004 \u0005[ויש אומרים]\u0006 \u0003ר' יוחנן:\u0004 מה שנאמר \"ראשי המטות\" בא ללמדנו שגם \u0003ביחיד מומחה\u0004 אפשר להתיר נדר.","\u0003אמר ר' חנינא:\u0004 בעל \u0003השותק\u0004 לאחר ששמע את אשתו נודרת \u0003על מנת למיקט\u0004 (לצער) את אשתו, כדי שתצטרך לסבול בקיום נדרה, אך בליבו הפר לה, הרי זה \u0003מפר\u0004 לה בפיו \u0003אפילו מכאן ועד עשרה ימים. מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 ממה ששנינו בברייתא: \u0003אימתי אמרו\u0004 שאם \u0003מת הבעל\u0004 (הארוס) \u0003נתרוקנה רשות לאב —\u0004 \u0003בזמן שלא שמע הבעל, או ששמע ושתק, או ששמע והפר ומת בו ביום. אבל\u0004 אם \u0003שמע וקיים, או ששמע ושתק ומת ביום של אחריו —\u0004 \u0003אין יכול להפר.\u0004","\u0003מאי לאו\u0004 \u0005[האם לא]\u0006 מה שאמרו \"שמע ושתק\" הוא אפילו \u0003בשותק על מנת למיקט\u0004 (לצער) אותה? ודוחים: \u0003לא,\u0004 מדובר שם דווקא \u0003בשותק על מנת לקיים.\u0004 ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 \u0003היינו\u0004 \u0005[הרי זה\u0006 בדיוק\u0005]\u0006 מה ששנינו \u0003או שמע וקיים! אלא\u0004 יש לתרץ בדרך אחרת, ששם מדובר \u0003בשותק סתם,\u0004 שלא נתכוון לכלום.","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב חסדא\u0004 ממקום אחר: שנינו: \u0003חומר\u0004 (חומרה) \u0003בהקם,\u0004 בקיום נדרים, \u0003מבהפר,\u0004 מבהפרת נדרים, \u0003ו\u0004חומר \u0003בהפר מבהקם;\u0004 כיצד? \u0003חומר בהקם —\u0004"],["\u0003שהשתיקה\u0004 עצמה \u0003מקיימת\u0004 את הנדר, \u0003ואין שתיקה מבטלת\u0004 אותו. כלומר, אם \u0003קיים\u0004 את נדר אשתו \u0003בלבו,\u0004 שהסכים בליבו שיהא נדר זה קיים — הרי זה \u0003קיים, הפר בלבו —\u0004 \u0003אינו מופר.\u0004 ואגב כך מוסיפים: אם \u0003קיים\u0004 נדר — \u0003אין יכול להפר\u0004 אותו עוד, וכן אם \u0003הפר —\u0004 \u0003אין יכול לקיים.\u0004 על כל פנים \u0003קתני\u0004 \u0005[שנה]\u0006 שם: \u0003שהשתיקה מקיימת, מאי לאו\u0004 \u0005[האם לא]\u0006 מדובר אפילו \u0003בשותק על מנת למיקט\u0004 (לצער)?","ודוחים: \u0003לא,\u0004 מדובר פה \u0003בשותק על מנת לקיים.\u0004 ואומרים: אם כן \u0003היינו\u0004 \u0005[הריהו\u0006 בדיוק\u0005]\u0006 כמו הדין הבא: \u0003קיים בלבו קיים!\u0004 ודוחים: \u0003אלא\u0004 \"שותק\" פירושו \u0003בשותק סתם,\u0004 שלא נתכוון לכלום.","על הברייתא שואלים: \u0003אשכחן\u0004 \u0005[מצאנו]\u0006 איפוא שיש \u0003חומר בהקם מבהפר, ואולם\u0004 שיש חומר \u0003בהפר מבהקם מנא לן\u0004 \u0005[מניין לנו],\u0006 כלומר, מה הוא דין זה? \u0003אמר ר' יוחנן: נשאלין על ההקם,\u0004 כלומר, יכול אדם להישאל לחכם, ולומר שהוא מתחרט על זה שקיים נדר שנדרה אשתו, ויתיר לו החכם את הקמתו, \u0003ואין נשאלין על ההפר.\u0004","\u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב כהנא\u0004 על ר' חנינא הסבור שהשותק על מנת למיקט יכול להפר אף לאחר כמה ימים. שנינו במדרש ההלכה על הכתוב: \u0003\"ואם החרש יחריש לה אישה\" וגו'\u0004 (במדבר ל, טו), ואמרו חכמים כי \u0003בשותק על מנת למיקט הכתוב מדבר. אתה אומר בשותק על מנת למיקט, או אינו אלא בשותק על מנת לקיים?\u0004 \u0003כשהוא אומר \"כי החריש לה\"\u0004 (במדבר ל, טו) \u0003הרי בשותק על מנת לקיים הכתוב מדבר, הא\u0004 \u0005[הרי]\u0006 \u0003מה אני מקיים\u0004 לשם מה נכתב עוד \u0003\"אם החרש יחריש לה אישה\"\u0004 — \u0003בשותק על מנת למיקט הכתוב מדבר,\u0004 שאף דבר זה נחשב כקיום! והרי זו \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לדברי ר' חנינא.","","לגופה של הלכה זו שואלים: \u0003ולוקים\u0004 \u0005[ושיעמיד,\u0006 יסביר\u0005]\u0006 התנא את הכתוב כפי שהסברנו את הברייתות: \u0003הא\u0004 \u0005[זה] —\u0006 \u0003בשותק על מנת לקיים, הא\u0004 \u0005[זה] —\u0006 \u0003בשותק סתם!\u0004 ומשיבים: \u0003קראי יתירי כתיבי\u0004 \u0005[כתובים יתרים נאמרו]\u0006 שם בהחרשה, ובהכרח יש לפרש שבכל אופן שהוא שותק הרי הנדר קיים.","ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רבא\u0004 על דברי ר' חנינא, שנינו: \u0003נדרה\u0004 בשבת \u0003עם חשכה,\u0004 כלומר, סמוך לחשיכה — \u0003מפר לה עד שלא\u0004 (לפני) \u0003חשכה, שאם לא הפר\u0004 לה קודם \u0003וחשכה —\u0004 \u0003אינו יכול\u0004 עוד \u0003להפר. אמאי\u0004 \u0005[מדוע]\u0006 כך? \u0003להוי\u0004 \u0005[שיהיה]\u0006 דינו של זה שאינו מפר משום כבוד השבת \u0003כשותק על מנת למיקט!\u0004 הרי זו שוב \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 על ר' חנינא. ועוד \u0003מתיב\u0004 \u0005[מקשה]\u0006 \u0003רב אשי\u0004 ממה ששנינו: אמר הבעל לאחר שנגמר היום בו נדרה אשתו: \u0003\"יודע אני שיש נדרים אבל איני יודע שיש מפירין\",\u0004 כלומר, שבעל יכול להפר נדרי אשתו. ולכן לא הפר לה — \u0003יפר\u0004 את הנדר אף לאחר זמן. אמר: \u0003\"יודע אני שיש מפירין אבל איני יודע שזה נדר\",\u0004 כלומר, שגם נדר זה הוא בכלל הנדרים שברשותו להפר. ולכן לא הפר — \u0003ר' מאיר אומר: לא יפר, וחכמים אומרים: יפר.\u0004","","\u0003ואמאי\u0004 \u0005[ומדוע]\u0006 לא יפר? \u0003ליהוי\u0004 \u0005[שיהא]\u0006 דינה של שתיקה בטעות, לפחות \u0003כשותק על מנת למיקט\u0004 שיכול להפר לאחר זמן לשיטת ר' חנינא! אלא משמע שאף במקרה זה שתיקתו נחשבת כקיום. ומסכמים: \u0003תיובתא\u0004 \u0005[קושיה חמורה]\u0006 לשיטת ר' חנינא הסבור ששותק על מנת למיקט יכול להפר אחר כמה ימים, ונדחו דבריו.","","\u0003ואלו נדרים שהוא,\u0004 הבעל או האב \u0003מפר: דברים שיש בהן ענוי נפש\u0004 לנודרת, כגון שנודרת: \u0003\"אם ארחץ\" ו\"אם לא ארחץ\", \"אם אתקשט\" ו\"אם לא אתקשט\".\u0004"],["\u0003אמר ר' יוסי: אין אלו נדרי ענוי נפש. ואלו הן נדרי ענוי נפש:\u0004 כגון ש\u0003אמרה \"קונם פירות העולם עלי\" —\u0004 \u0003הרי זה יכול להפר,\u0004 מפני שבודאי יש בכך עינוי נפש. אבל אם אמרה \u0003\"\u0004קונם \u0003פירות מדינה זו עלי\" —\u0004 \u0003יביא לה מ\u0004פירות \u0003מדינה אחרת.\u0004 וכן אם אמרה \u0003\"\u0004קונם \u0003פירות חנווני זה עלי\" —\u0004 \u0003אינו יכול להפר,\u0004 שאין זה עינוי נפש, שהרי יכול לקנות פירות מחנווני אחר. \u0003ואם לא היתה פרנסתו\u0004 (צרכי מחייתו) \u0003אלא ממנו\u0004 מחנווני זה — \u0003הרי זה יפר,\u0004 אלו \u0003דברי ר' יוסי.\u0004","שואלים על המשנה: וכי רק \u0003נדרי ענוי נפש הוא\u0004 ש\u0003מפר,\u0004 ונדרים \u0003שאין בהן ענוי נפש אינו מפר? והא תניא\u0004 \u0005[והרי שנינו\u0006 בברייתא\u0005]:\u0006 מה שנאמר: \u0003\"בין איש לאשתו בין אב לבתו\"\u0004 (במדבר ל, יז) — \u0003מלמד שהבעל מפר נדרים שבינו לבינה,\u0004 גם אם אין בהם עינוי נפש, אלא שהם פוגעים ביחסים ביניהם!","\u0003אמרי\u0004 \u0005[אומרים]:\u0006 \u0003הלין והלין\u0004 \u0005[אלה ואלה]\u0006 \u0003מפר, מיהו\u0004 \u0005[אבל]\u0006 יש הבדל ביניהם; כי נדרים של \u0003ענוי נפש,\u0004 כשהוא מפר — \u0003מפר לעולם. אבל\u0004 נדרים ש\u0003אין בהן ענוי נפש\u0004 אלא רק בינו לבינה, \u0003כדאיתה תחותיה\u0004 \u0005[כאשר היא תחתיו,\u0006 נשואה לו\u0005] —\u0006 \u0003הויא\u0004 \u0005[הרי זו]\u0006 \u0003הפרה, מכי\u0004 \u0005[מזמן]\u0006 ש\u0003מגרש לה\u0004 (אותה) — \u0003חייל עלה\u0004 \u0005[חל עליה]\u0006 \u0003נדרה.\u0004 וזה, כאמור — \u0003בדברים שבינו לבינה שאין בהן ענוי נפש. אבל\u0004 בדברים שבינו לבינה ו\u0003יש בהן\u0004 גם \u0003ענוי נפש —\u0004 \u0003לא חייל\u0004 \u0005[חל]\u0006 \u0003עליה נדרה\u0004 גם לאחר שיצאה מרשות בעלה.","ושואלים: \u0003ודברים שאין בהן ענוי נפש, כי\u0004 \u0005[כאשר]\u0006 \u0003מגרש לה\u0004 (אותה), האם \u0003חיילא עלה\u0004 \u0005[חלים עליה]?\u0006 \u0003והא תנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]\u0006 שכשאשה אסרה בקונם את מעשה ידיה לבעלה, \u0003ר' יוחנן בן נורי אומר: יפר\u0004 את הנדר, \u0003שמא יגרשנה\u0004 \u0003ותהא אסורה לו\u0004 מאותה שעה לעולם במעשה ידיה, ולא יוכל להחזירה. \u0003אלמא\u0004 \u0005[מכאן]\u0006 אנו למדים: \u0003כי\u0004 \u0005[כאשר]\u0006 \u0003מגרש לה\u0004 \u0005[אותה]\u0006 \u0003ומפר לה מעיקרא\u0004 \u0005[מתחילה]\u0006 בזמן שהיא תחתיו — \u0003הויא\u0004 \u0005[הרי זו]\u0006 \u0003הפרה\u0004 לעולם. ואין אומרים שכיון שאין בנדר עינוי נפש יחול הנדר לאחר הגירושין!","על כן \u0003אמרי\u0004 \u0005[אומרים]\u0006 באופן אחר: \u0003הלין והלין\u0004 \u0005[אלה ואלה]\u0006 נדרי עינוי נפש ונדרים שבינו לבינה, הפרתו \u0003הויא\u0004 \u0005[הריהי]\u0006 \u0003הפרה\u0004 לעולם. \u0003אלא,\u0004 יש הבדל אחר ביניהם: \u0003נדרי ענוי נפש\u0004 כשמפר הריהו \u0003מפר\u0004 לגמרי, \u0003בין לעצמו\u0004 כאשר היא נשואה או ראויה להינשא לו, \u0003ובין לאחרים\u0004 כאשר תינשא לאיש אחר. ואילו נדרים ש\u0003אין בהן ענוי נפש, לעצמו\u0004 בצד שהנדר נוגע אליו — \u0003מפר\u0004 לעולם, אבל דברים שנוגעים \u0003לאחרים אינו מפר. ו\u0004לפי זה \u0003הכי קתני\u0004 \u0005[כך שנה\u0006 במשנה\u0005]:\u0006 \u0003אלו נדרים שהוא מפר בין לעצמו ובין לאחרים —\u0004 \u0003נדרים שיש בהן ענוי נפש.\u0004","שנינו במשנה בכלל נדרי עינוי נפש כשאמרה \u0003\"אם ארחץ\",\u0004 ור' יוסי חולק ואומר שאין זה נדר עינוי נפש. ושואלים: \u0003היכי קאמר\u0004 \u0005[כיצד היא אומרת]?\u0006 שהרי כשאומרת \"אם ארחץ\" משמע שלא זה הוא עיקר נדרה, אלא נדרה בדבר מסויים, שנתלה באם תרחץ או לא תרחץ. \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמרה\u0004 בלשון \u0003\"קונם פירות עולם עלי אם ארחץ\" —\u0004 \u0003למה לה הפרה\u0004 כלל? \u0003לא תרחץ ולא ליתסרן\u0004 \u0005[ייאסרו]\u0006 \u0003פירות\u0004 ה\u0003עולם אלו עלה\u0004 \u0005[עליה]!\u0006","\u0003ועוד\u0004 יש לשאול מצד אחר: \u0003בהא לימא\u0004 \u0005[ב\u0006נדר כגון \u0005זה יאמר]\u0006 \u0003ר' יוסי אין אלו נדרי ענוי נפש?\u0004 הלא יש לחשוש \u0003דלמא רחצה ואיתסרו\u0004 \u0005[שמא תרחץ וייאסרו]\u0006 \u0003פירות עולם עלה\u0004."],["\u0003ואלא\u0004 נפרש כך: \u0003דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]\u0006 \u0003\"קונם הנאת רחיצה עלי לעולם אם ארחץ\" משום הכי\u0004 \u0005[כך]\u0006 \u0003מיפר לה. דהיכי תעביד\u0004 \u0005[ש\u0006כן \u0005כיצד תעשה]\u0006 בלא הפרה? אם \u0003תרחץ\u0004 — על ידי כך \u0003מתסרא\u0004 \u0005[נאסרת]\u0006 \u0003הנאת רחיצה עלה\u0004 \u0005[עליה],\u0006 אם \u0003לא תרחץ —\u0004 \u0003אית\u0004 \u0005[יש]\u0006 \u0003לה ניוולא\u0004 \u0005[ניוול],\u0006 כיעור ומיאוס על ידי כך. \u0003ור' יוסי\u0004 שאומר שאין אלה נדרי עינוי נפש \u0003סבר\u0004 \u0005[סבור]:\u0006 \u0003אפשר\u0004 ש\u0003לא רחצה\u0004 \u0005[תרחץ],\u0006 \u0003ולניוול לא חיישינן\u0004 \u0005[אין אנו חוששין].\u0006","ומקשים: \u0003אי הכי\u0004 \u0005[אם כך]\u0006 אתה מפרש, \u0003ליתני הכי\u0004 \u0005[שישנה כך],\u0006 \u0003רבי יוסי אומר:\u0004 \u0003תנאי זה אין בו\u0004 משום \u0003ענוי נפש!\u0004","\u0003אלא\u0004 צריך לפרש \u0003דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003\"הנאת רחיצה עלי לעולם אם ארחץ היום\". ור' יוסי סבר:\u0004 אם לא תרחץ היום אין בכך כלום, כיון ש\u0003ניוול דחד יומא\u0004 \u0005[של יום אחד]\u0006 \u0003לא שמיה\u0004 \u0005[אין שמו]\u0006 \u0003ניוול.\u0004"],["ושואלים: \u0003שנית\u0004 \u0005[תירצת,\u0006 הסברת\u0005]\u0006 את הביטוי כשנדרה \u0003\"אם ארחץ\".\u0004 אבל \u0003\"אם לא ארחץ\" היכי דמי\u0004 \u0005[כיצד הוא בדיוק]?\u0006 \u0003אלימא דאמרה\u0004 \u0005[אם לומר שאומרת]\u0006 כך: \u0003\"תיתסר\u0004 \u0005[תיאסר]\u0006 \u0003הנאת רחיצה לעולם עלי אם לא ארחץ היום\" —\u0004 \u0003למה לה הפרה? תתסחי\u0004 \u0005[תרחץ]\u0006 היום! \u0003אמר רב יהודה: דאמרה\u0004 \u0005[שאומרת]\u0006 \u0003\"הנאת רחיצה\u0004 אסורה \u0003עלי לעולם אם לא ארחץ במי משרה\"\u0004 (מים ששורים בהם את הפשתים), שהם מסריחים. ויכול להפר נדר זה, לפי שגורם לה ניוול.","ושואלים: אם כן \u0003דכוותיה דקתני\u0004 \u0005[כיוצא בו מה שהוא שונה]\u0006 \u0003\"אם לא אתקשט\"\u0004 צריך אתה לפרש ביטוי זה של נדר באותו אופן — שתולה את הנדר \"הנאת קישוט עלי\" בדבר המאוס כגון: \u0003אם לא אתקשט בנפט.\u0004 אולם דבר זה \u0003לכלוך הוא\u0004 ולא ניתן לקרוא לכך קישוט!","אלא \u0003אמר [רב יהודה]\u0004 כך צריך לפרש: \u0003דאמרה\u0004 \u0005[שהיא אומרת]\u0006 \u0003\"הנאת רחיצה\u0004 אסורה \u0003לעולם עלי אם ארחץ היום, ושבועה שלא ארחץ\u0004 היום \u0003\",\u0004 שעל ידי צירוף הנדר והשבועה אוסרת עצמה ברחיצה לעולם. או שאמרה \u0003\"הנאת קישוט עלי לעולם אם אתקשט היום, ושבועה שלא אתקשט\".\u0004","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003רבינא לרב אשי:\u0004 לפי \u0003האי\u0004 \u0005[\u0006פירוש \u0005זה]\u0006 \u0003\"אלו נדרים ושבועות\" מיבעי ליה למיתני\u0004 \u0005[צריך היה לו לשנות]\u0006 במשנתנו! \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תני\u0004 \u0005[שנה]\u0006 באמת כך במשנתנו: \u0003אלו נדרים ושבועות. ואיבעית אימא\u0004 \u0005[ואם תרצה אמור]:\u0006 \u0003שבועות נמי\u0004 \u0005[גם כן]\u0006 \u0003היינו\u0004 \u0005[הריהן]\u0006 בכלל לשון \u0003נדרים. דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005]:\u0006 האומר \u0003\"כנדרי רשעים\"\u0004 — הרי זה \u0003נדר בנזיר ובקרבן ובשבועה.\u0004 משמע שאף שבועה היא בכלל לשון נדר.","ושואלים: \u0003ו\u0004כי \u0003אמרו\u0004 \u0005[אומרים]\u0006 \u0003רבנן\u0004 \u0005[חכמים]:\u0006 \u0003רחיצה אית\u0004 \u0005[יש]\u0006 \u0003בה ענוי נפש כי לא רחצה\u0004 \u0005[כאשר אינה רוחצת]?\u0006 \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003אף על פי שאסור\u0004 ביום הכיפורים \u0003בכולן,\u0004 בכל סוגי העינוי: באכילה ושתייה, רחיצה וסיכה, תשמיש המיטה ונעילת הסנדל — \u0003אין ענוש כרת אלא באוכל ושותה\u0004 \u0003ועושה מלאכה בלבד. ואי אמרת\u0004 \u0005[ואם אתה אומר]\u0006 \u0003כי לא רחצה\u0004 \u0005[כאשר אינה רוחצת]\u0006 \u0003איכא\u0004 \u0005[יש\u0006 בכך\u0005]\u0006 \u0003ענוי,\u0004 ומשום כך יש רשות לבעל להפר נדר כזה של אשתו, אם כן \u0003ביום הכיפורים כי רחץ\u0004 \u0005[כאשר\u0006 אדם מישראל \u0005רוחץ]\u0006 \u0003ליחייב\u0004 \u0005[שיתחייב]\u0006 על כך \u0003כרת,\u0004 שהרי נאמר ביום הכיפורים: \"כי כל הנפש אשר לא תעונה בעצם היום הזה ונכרתה מעמיה\" (ויקרא כג, כט) והרוחץ ביטל על ידי רחיצתו סוג זה של עינוי!","\u0003אמר רבא: מענינא דקרא\u0004 \u0005[מעניינו של הכתוב]\u0006 אנו למדים מה משמעות אותו עינוי. \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003יום הכיפורים דכתיב\u0004 \u0005[שנאמר]\u0006 בו \u0003\"\u0004בעשור לחודש \u0003תענו את נפשתיכם\"\u0004 (ויקרא טז, כט), עניינו — \u0003מילתא דידע עינויא השתא\u0004 \u0005[דבר שיודע\u0006 ומרגיש את \u0005העינוי\u0006 שבו כבר \u0005עכשיו]\u0006 ביום הכיפורים עצמו, ובמניעת אכילה ושתייה סובל תוך זמן קצר. אבל במניעת \u0003רחיצה לא ידע עינויא השתא\u0004 \u0005[אינו יודע\u0006 מרגיש את \u0005העינוי עכשיו],\u0006 אלא הצער בא לאחר זמן. ומצד שני \u0003גבי\u0004 \u0005[אצל]\u0006 \u0003נדרים דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"כל נדר וכל שבעת אסר לענת נפש...\u0004 ואישה יפירנו\u0003\"\u0004 (במדבר ל, יד), עניינו — \u0003מילתא דאתיא ליה\u0004 \u0005[דבר שבאה בו]\u0006 \u0003לידי ענוי, וכי לא רחצה אתיא\u0004 \u0005[וכאשר אינה רוחצת באה]\u0006 בסופו של דבר \u0003לידי ענוי.\u0004","\u0003ו\u0004עוד \u0003רמי\u0004 \u0005[ומשליכים\u0006 מראים סתירה\u0005]\u0006 מדברי \u0003ר' יוסי\u0004 על דברי \u0003ר' יוסי\u0004 עצמו, ששנינו: \u0003מעיין של בני העיר\u0004 והיו גם אחרים נזקקים למי המעיין, אם המדובר ב\u0003חייהן\u0004 של בני העיר, כלומר, הצורך במים לשתייה, \u0003וחיי אחרים —\u0004 \u0003חייהן קודמין לחיי אחרים.\u0004 וכן אם היה צורך במעיין להשקיית בהמות \u0003בהמתם [ובהמת אחרים —\u0004 \u0003בהמתם] קודמת לבהמת אחרים.\u0004 וכן \u0003כביסתן וכביסת אחרים —\u0004 \u0003כביסתן קודמת לכביסת אחרים.\u0004 אבל היה הצורך במי המעיין ל\u0003חיי אחרים וכביסתן\u0004 של בני העיר — \u0003חיי אחרים קודמין לכביסתן.\u0004","\u0003ר' יוסי אומר:\u0004 אף \u0003כביסתן קודמת לחיי אחרים,\u0004 משום שמניעת כביסה יש בה צער מרובה וסכנה. ומעתה \u0003השתא\u0004 \u0005[עכשיו,\u0006 הרי\u0005]\u0006 אם \u0003כביסה\u0004 של בגדים \u0003אמר ר' יוסי יש בה צער\u0004 ועינוי במניעתה,"],["\u0003גוף כולו לא כל שכן\u0004 שאם אינו מתרחץ שיש לו צער?! ודוחים: \u0003אמרי\u0004 \u0005[אומרים]\u0006 : \u0003אין\u0004 \u0005[כן],\u0006 צער מניעת \u0003כביסה אלימא\u0004 \u0005[חזקה,\u0006 גדולה\u0005]\u0006 \u0003לר' יוסי\u0004 מצער מניעת רחיצת הגוף. וכפי ש\u0003אמר שמואל: האי ערבוביתא דרישא\u0004 \u0005[לכלוך זה שבראש] —\u0006 \u0003מתיא\u0004 \u0005[מביא]\u0006 \u0003לידי עוירא\u0004 \u0005[עיוורון],\u0006 \u0003ערבוביתא דמאני\u0004 \u0005[לכלוך שבבגדים] —\u0006 \u0003מתיא\u0004 \u0005[מביא]\u0006 \u0003לידי שעמומיתא\u0004 \u0005[שגעון],\u0006 \u0003ערבוביתא דגופא\u0004 \u0005[לכלוך שבגוף] —\u0006 \u0003מתיא\u0004 \u0005[מביא]\u0006 \u0003לידי שיחני וכיבי\u0004 \u0005[שחינים ופצעים]\u0006 שאין הם כה חמורים כשגעון וכעיוורון. ומכאן יש לומר כי לר' יוסי לכלוך בגדים מסוכן יותר מאשר לכלוך הגוף.","ובאותו ענין מספרים: \u0003שלחו\u0004 חכמים \u0003מתם\u0004 \u0005[משם,\u0006 מארץ ישראל לבבל\u0005]\u0006 : \u0003הזהרו בערבוביתא\u0004 \u0005[בלכלוך]\u0006 שדבר זה יכול להביא למחלות. \u0003הזהרו בחבורה,\u0004 שתלמדו תורה בחבורה ולא ביחידות. \u0003הזהרו בבני עניים\u0004 ללמדם, \u0003שמהן תצא תורה, שנאמר: \"יזל מים מדליו\"\u0004 (במדבר כד, ז), שמפרשים: מן הדלים שבו, \u0003שמהן תצא תורה\u0004 המשולה למים (\"וזרעו כמים רבים\").","ובאותו ענין מבררים: \u0003ומפני מה\u0004 בדרך כלל \u0003אין מצויין תלמידי חכמים לצאת תלמידי חכמים מבניהן\u0004 אלא מבני עניים שאינם תלמידי חכמים? \u0003אמר רב יוסף: שלא יאמרו\u0004 אנשים: \u0003תורה ירושה היא להם,\u0004 ולכן אין מצוי שיהיו כל בני תלמידי החכמים תלמידי חכמים גם הם. \u0003רב ששת בריה\u0004 \u0005[בנו]\u0006 של \u0003רב אידי אומר: כדי שלא יתגדרו\u0004 (יתגאו) \u0003על הצבור,\u0004 אם היו יודעים שאף הם יהיו חכמים כאבותיהם. \u0003מר זוטרא אומר: מפני שהן מתגברין על הצבור\u0004 מפני כבוד אבותיהם, ונענשים משום כך. \u0003רב אשי אומר: משום דקרו לאינשי \"חמרי\"\u0004 \u0005[שקוראים לאנשים\u0006 רגילים \u0005\"חמורים\"].\u0006","\u0003רבינא אומר:\u0004 הם נענשים משום \u0003שאין מברכין בתורה תחלה.\u0004 וכפי ש\u0003אמר רב יהודה אמר רב: מאי דכתיב\u0004 \u0005[מהו שנאמר]:\u0006 \u0003\"מי האיש החכם ויבן את זאת\u0004 ואשר דבר פי ה' אליו ויגידה על מה אבדה הארץ נצתה כמדבר מבלי עובר\u0003\"\u0004 (ירמיה ט, יא)? \u0003דבר זה\u0004 (\"על מה אבדה הארץ נצתה כמדבר מבלי עובר\") \u0003נשאל לחכמים\u0004 (\"האיש החכם\") \u0003ולנביאים\u0004 (\"ואשר דיבר פי ה' אליו\") \u0003ולא פירשוהו,\u0004","\u0003עד שפירשו הקדוש ברוך הוא בעצמו, דכתיב\u0004 \u0005[שנאמר]\u0006 מיד אחר כך: \u0003\"ויאמר ה' על עזבם את תורתי\u0004 אשר נתתי לפניהם ולא שמעו בקולי ולא הלכו בה\" (ירמיה ט, יב). ולכאורה \u0003היינו\u0004 \u0005[זהו]\u0006 \u0003\"לא שמעו בקולי\" היינו\u0004 \u0005[זהו]\u0006 \u0003\"לא הלכו בה\"! אמר רב יהודה אמר רב:\u0004 הכוונה בביטוי \"לא הלכו בה\" היא \u0003שאין מברכין בתורה תחלה,\u0004 ועל כך נענשים בעונשים החמורים הנזכרים שם.","ועוד בענין הכביסה, מסופר: \u0003איסי בר יהודה לא אתא\u0004 \u0005[בא]\u0006 \u0003למתיבתא\u0004 \u0005[לישיבה]\u0006 של \u0003ר' יוסי תלתא יומי\u0004 \u0005[שלשה ימים].\u0006 \u0003אשכחיה\u0004 \u0005[מצא אותו]\u0006 \u0003ורדימוס\u0004 בנו של \u0003ר' יוסי, אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מאי טעמא\u0004 \u0005[מה טעם]\u0006 \u0003לא אתי מר לבי מדרשא\u0004 \u0005[לא בא אדוני לבית המדרש]\u0006 של \u0003אבא הא תלתא יומין\u0004 \u0005[זה שלשה ימים]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003כי טעמיה דאבוך לא ידענא, היכא איתאי\u0004 \u0005[כאשר\u0006 את \u0005טעמו,\u0006 סברתו \u0005של אביך אינני יודע, איך אבוא]?\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003לימא מר מאי קאמר ליה, דלמא ידענא טעמיה\u0004 \u0005[יאמר אדוני מה אמר לו\u0006 אבי, \u0005שמא יודע אני\u0006 את \u0005טעמו].\u0006 \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003הא דתניא\u0004 \u0005[זו ששנויה\u0006 בברייתא\u0005]\u0006 \u0003ר' יוסי אומר: כביסתן קודמין לחיי אחרים, קרא מנלן\u0004 \u0005[כתוב,\u0006 פסוק המלמד על כך \u0005מניין לנו]?\u0006","\u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003דכתיב\u0004 \u0005[שנאמר]\u0006 בערי הלויים: \u0003\"ומגרשיהם יהיו לבהמתם\u0004 ולרכושם ולכל חיתם\u0003\"\u0004 (במדבר לה, ג). ונברר \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיתם\"? אילימא\u0004 \u0005[אם תאמר]\u0006 \u0003חיה\u0004 ממש — \u0003והלא חיה בכלל בהמה היא,\u0004 ודי היה במה שאמר לפני כן \"בהמתם\". \u0003אלא מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 \u0003\"חיתם\"\u0004 — אם תאמר \u0003חיותא\u0004 \u0005[חייהם,\u0006 חיותם\u0005]\u0006 \u0003ממש, פשיטא\u0004 \u0005[פשוט]\u0006 שלשם כך קיבלו הלויים את הערים! \u0003אלא לאו\u0004 \u0005[האם אין\u0006 הכוונה\u0005]\u0006 לענין \u0003כביסה, דהא איכא צערא דערבוביתא\u0004 \u0005[שהרי יש צער של לכלוך]\u0006 במניעת כביסה, והרי זה כצרכי חיים (\"חייתם\") ולכן קודמת כביסתם של בני העיר לחייהם של אחרים.","על הנדרים \"אם ארחץ\" \"אם לא ארחץ\" \"אם אתקשט\" ו\"אם לא אתקשט\" \u0003אמר ר' יוסי\u0004 במשנה: \u0003אין אלו נדרי ענוי נפש. איבעיא להו\u0004 \u0005[נשאלה להם\u0006 ללומדים\u0005]:\u0006 \u0003לר' יוסי, מהו שיפר\u0004 נדרים אלה \u0003משום דברים שבינו לבינה?\u0004 ומציעים: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 פתרון לדבר ממה ש\u0003אמר ר' יוסי: אין אלו נדרי עינוי נפש,\u0004 משמע: \u0003אבל דברים שבינו לבינה הויין\u0004 \u0005[הינם].\u0006","ודוחים: \u0003דלמא לדידהו קאמר להו\u0004 \u0005[שמא,\u0006 לחכמים ולשיטתם \u0005שלהם אמר להם]:\u0006 \u0003לדידי\u0004 \u0005[ל\u0006שיטתי \u0005שלי]\u0006 \u0003אפילו דברים שבינו לבינה לא הויין\u0004 \u0005[אינם].\u0006 \u0003לדידכו, דאמריתו הויין\u0004 \u0005[לשיטה שלכם, שאתם אומרים\u0006 שאלה \u0005הם]\u0006 \u0003נדרי עינוי נפש —\u0004 \u0003אודו\u0004 \u0005[הודו]\u0006 \u0003לי\u0004 ש\u0003אין אלו נדרי עינוי נפש.\u0004","ואם כן חוזרת השאלה: \u0003מאי\u0004 \u0005[מה]\u0006 סבור ר' יוסי? \u0003רב אדא בר אהבה אומר: מפר\u0004 משום דברים שבינו לבינה, \u0003רב הונא אומר: אין מפר\u0004"],["\u0003שלא מצינו\u0004 (מצאנו) \u0003שועל שמת בעפר פיר\u0004 (חפירה) שהוא חי בה — כך אין הדבר מפריע לבעל לתשמיש אף על פי שאין אשתו מקושטת.","ומעירים: \u0003תניא כוותיה\u0004 \u0005[שנויה\u0006 ברייתא \u0005כשיטתו]\u0006 של \u0003רב אדא בר אהבה: דברים שיש בהן עינוי נפש —\u0004 \u0003מפר, בין\u0004 כשהנדרים הם בדברים \u0003בינו לבינה, בין\u0004 כשהם \u0003בינה לבין אחרים.\u0004 נדרים \u0003שאין בהן עינוי נפש; בינו לבינה —\u0004 \u0003מפר, בינה לבין אחרים —\u0004 \u0003אינו מפר. כיצד? אמרה \"קונם פירות עלי\" —\u0004 \u0003הרי זה יפר,\u0004 שהוא בכלל נדרי עינוי נפש. \u0003\"קונם שאיני עושה לפי אבא, לפי אחיך, לפי אביך, לפי אחי, ושלא אתן תבן לפני בהמתך ומים לפני בקרך\" —\u0004 \u0003אין יכול להפר,\u0004 שאין נדרים אלה נוגעים ביחסים ביניהם, וגם אינם עינוי נפש.","אם נדרה \u0003\"שלא אכחול\u0004 את עיני \u0003\",\u0004 או \u0003\"שלא אפקוס\u0004 (בצבע אדום) את לחיי \u0003\",\u0004 או \u0003\"שלא אשמש מטתי\" —\u0004 \u0003יפר משום דברים שבינו לבינה.\u0004","אם אמרה \u0003\"שלא אציע לך\u0004 את \u0003מטתך, ושלא אמזוג לך את הכוס, ושלא ארחץ לך פניך ידיך ורגליך\" —\u0004 \u0003אין צריך להפר,\u0004 כי נדרים אלה אינם חלים כלל, משום שיש לה התחייבות מוקדמת מכוח הסכם הנישואין לעשות זאת.","\u0003רבן גמליאל אומר:\u0004 מכל מקום \u0003יפר, שנאמר: \"לא יחל דברו\"\u0004 (במדבר ל, ג), שאין ראוי לאדם לנדור ולא לקיים את הנדר. \u0003דבר אחר\u0004 פירשו: \u0003\"לא יחל דברו\" —\u0004 \u0003מכאן לחכם שאין מתיר נדרי עצמו.\u0004","ולאחר שהבאנו את כל לשון הברייתא נברר, \u0003מאן שמעינן\u0004 \u0005[מי\u0006 הוא ש\u0005שמענו\u0006 אותו\u0005]\u0006 ש\u0003אמר\u0004 כי דבריה של אשה האומרת \u0003\"שלא אכחול ושלא אפקוס\" דברים שבינו לבינה הויין\u0004 \u0005[הם] —\u0006 \u0003ר' יוסי\u0004 הוא, שהרי לדעת חכמים הרי זה בכלל עינוי נפש, \u0003וקתני\u0004 \u0005[ושנה]\u0006 ש\u0003מפר\u0004 בנדרים כאלו \u0003משום דברים שבינו לבינה,\u0004 ואם כן הרי זו הוכחה לשיטת רב אדא בר אהבה.","לגופה של הברייתא בה \u0003אמר מר\u0004 \u0005[החכם]:\u0006 הנודרת \u0003\"שלא אשמש מטתי\" —\u0004 \u0003יפר משום דברים שבינו לבינה.\u0004 שואלים: \u0003היכי דמי\u0004 \u0005[כיצד בדיוק\u0006 היה הדבר\u0005]\u0006? \u0003אילימא\u0004 \u0005[אם תאמר]\u0006 ש\u0003אמרה: \"הנאת תשמישי\u0004 אסורה \u0003עליך\", למה לי הפרה\u0004 כלל? \u0003הא\u0004 \u0005[הרי]\u0006 היא \u0003משועבדת ליה\u0004 \u0005[לו]\u0006 לתשמיש מעצם הנשואין, ואין בכוחה לבטל את הדבר בנדר! \u0003אלא באומרת \"הנאת תשמישך\u0004 אסורה \u0003עלי\". וכ\u0004דעת \u0003רב כהנא,\u0004","ש\u0003אמר רב כהנא:\u0004 האומרת \u0003\"הנאת תשמישי\u0004 אסורה \u0003עליך\" —\u0004 בעלה \u0003כופה ומשמשתו.\u0004 אבל אם אמרה \u0003\"הנאת תשמישך\u0004 אסורה \u0003עלי\" —\u0004 \u0003יפר,\u0004 ומדוע צריך להפר למרות שהיא מחוייבת בכך — לפי \u0003שאין מאכילין את האדם דבר האסור לו,\u0004 והיא הרי אסרה על עצמה את ההנאה שבכך. ואף שאין זה מפקיע את השעבוד, מכל מקום אינה יכולה לשמש בלא ליהנות.","ושואלים: \u0003מאן תנא הא דתניא\u0004 \u0005[מי הוא\u0006 התנא ש\u0005שנה\u0006 את \u0005זו ששנינו\u0006 בברייתא\u0005]\u0006 : \u0003דברים המותרים ואחרים נהגו בהן איסור —\u0004 \u0003אי אתה רשאי לנהוג בהם היתר כדי לבטלן\u0004 ממה שנהגו, \u0003משום שנאמר \"לא יחל דברו\"\u0004 משמע שכיון שגזר אדם על עצמו איסור (\"דברו\"), אף שהדבר מותר מן הדין — יש בכך מעין נדר, ואסור לחללו. \u0003דבר אחר: \"לא יחל דברו\" —\u0004 \u0003מכאן לתלמיד חכם שאין מפר נדרי עצמו. מני\u0004 \u0005[\u0006שיטת \u0005מי היא]\u0006 — שיטת \u0003רבן גמליאל היא,\u0004 שאמר שצריך להפר לאשה נדר שמן הדין אינו חל.","\u0003בעא מיניה\u0004 \u0005[שאל ממנו]\u0006 \u0003רבא מרב נחמן:\u0004 אשה שנדרה מ\u0003תשמיש המטה, לרבנן\u0004 \u0005[ל\u0006דעת \u0005חכמים],\u0006 האם בכלל \u0003עינוי נפש הוא או דברים שבינו לבינה\u0004 הוא? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003תניתוה\u0004 \u0005[שניתם אותה]\u0006 כבר במשנה את התשובה לשאלה זו. ששנינו, שהאשה שנדרה ובכלל דבריה אמרה \u0003\"ונטולה אני\u0004 (אסורה הנאתי) \u0003מן היהודים\",\u0004 לענין תשמיש"],["\u0003יפר חלקו,\u0004 כלומר, את חלק הנדר הנוגע לו, שתהא מותרת לו, \u0003ומשמשתו. ותהא נטולה מן היהודים,\u0004 שאם תתגרש ממנו הריהי אסורה לכל בגלל הנדר. \u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שדבר זה בכלל \u0003נדר ענוי נפש הוי\u0004 \u0005[הוא],\u0006 \u0003אמאי\u0004 \u0005[מדוע]\u0006 \u0003תהא נטולה מן היהודים?\u0004 והרי אמרנו שכאשר מתיר נדרי עינוי נפש הריהו מתיר לכל! \u0003שמע מינה\u0004 \u0005[למד מכאן]\u0006 ש\u0003דברים שבינו לבינה הויין\u0004 \u0005[הם],\u0006 ומשום כך רק לעצמו הוא מתיר.","ואומרים: \u0003לרבנן תבעי\u0004 \u0005[ל\u0006דעת \u0005חכמים\u0006 עדיין \u0005תישאל]\u0006 \u0003לך\u0004 השאלה, \u0003משום\u0004 ש\u0003\"נטולה אני מן היהודים\" ר' יוסי\u0004 הוא \u0003קתני לה\u0004 \u0005[\u0006ש\u0005שונה אותה],\u0006 ש\u0003אמר רב הונא: כוליה פירקין\u0004 \u0005[כל פרקנו\u0006 זה\u0005]\u0006 כשיטת \u0003ר' יוסי היא. ממאי\u0004 \u0005[ממה]\u0006 הוא מוכיח זאת — \u0003כיון דקתני\u0004 \u0005[שהוא שונה]\u0006 במשנתנו ש\u0003ר' יוסי אומר\u0004 ש\u0003אין אלו נדרי עינוי נפש,\u0004 אם כן \u0003למה ליה תו למיתנא\u0004 \u0005[לו עוד לשנות]\u0006 בסופה \u0003\"הרי זה יפר, דברי ר' יוסי\"? שמע מינה\u0004 \u0005[למד מכאן]\u0006 כי \u0003מכאן ואילך,\u0004 כל מה שיש במשנה — שיטת \u0003ר' יוסי היא.\u0004 ומן המשנה אפשר איפוא לדעת מה דעת ר' יוסי, אבל לא נתפרשה דעת חכמים בענין זה.","\u0003אמר שמואל משמיה\u0004 \u0005[משמו]\u0006 של \u0003לוי: כל נדרים\u0004 של עינוי נפש \u0003בעל מפר לאשתו, חוץ מן \"הנאתי\u0004 אסורה \u0003על פלוני\" שאינו מפר,\u0004 לפי שהוא נדר שבינה לבין אחרים לגמרי. \u0003אבל\u0004 אם אומרת \u0003\"הנאת פלוני\u0004 אסורה \u0003עלי\" —\u0004 \u0003מפר,\u0004 שהיא בכלל נדרי עינוי נפש, שכן, אולי תזדקק לאותו אדם, ובגלל הנדר לא תוכל ליהנות ממנו, ונמצא שגרמה לעצמה עינוי נפש בנדר זה.","ומקשים: \u0003תנן\u0004 \u0005[שנינו\u0006 במשנה\u0005]:\u0006 \u0003\"פירות מדינה זו\u0004 אסורים \u0003עלי\" —\u0004 \u0003יביא לה ממדינה\u0004 \u0003אחרת,\u0004 והרי נדר זה הוא כנדר שאסרה הנאת פלוני עליה, ולדעת שמואל מדוע לא יפר? \u0003אמר רב יוסף:\u0004 במשנה מדובר במקרה \u0003דקאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]\u0006 בנדרה \"פירות מדינה זו \u0003שתביא\u0004 אסורים עלי\". כלומר, שלא אסרה על עצמה הנאת פירות אלה בכלל, אלא רק את הפירות שהבעל עצמו מביא לה. ונמצא שהיא יכולה ליהנות מן אותם פירות אם יביאם אחר או היא עצמה.","ומקשים עוד מהמשך המשנה: \u0003תא שמע\u0004 \u0005[בוא\u0006 ו\u0005שמע]\u0006 ממה ששנינו \u0003\"פירות חנוני זה עלי\" —\u0004 \u0003אין יכול להפר.\u0004 ומדוע? והרי אמר שמואל שאם אסרה הנאת אחרים עליה יכול להפר! ומשיבים: \u0003הכא נמי\u0004 \u0005[כאן גם כן]\u0006 מדובר \u0003דקא אמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]\u0006 בנדרה \"פירות חנווני זה \u0003שתביא אתה,\u0004 עלי\".","ומקשים, והרי על כך שנינו: \u0003לא היתה פרנסתו אלא ממנו\u0004 מחנווני זה — \u0003הרי זה יפר. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 שמדובר במקרה \u0003דקא אמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]\u0006 \u0003\"שתביא אתה\", אמאי\u0004 \u0005[מדוע]\u0006 \u0003יפר?\u0004 הרי יכול הוא להביא לה על ידי אחרים! \u0003אלא מדסיפא\u0004 \u0005[מ\u0006תוך \u0005שהסוף,\u0006 המשך המשנה\u0005]\u0006 במקרה ש\u0003לא מייתי\u0004 \u0005[מביא]\u0006 ה\u0003בעל\u0004 דווקא \u0003הוי\u0004 \u0005[הוא],\u0006 אלא שאוסרת על עצמה בכל מקרה, הרי אף \u0003רישא\u0004 \u0005[בתחילה]\u0006 מדובר שאוסרת פירות \u0003דקא מייתא\u0004 \u0005[שמביאה]\u0006 אף \u0003היא\u0004 בעצמה, ואף על פי כן אין הבעל מפר. וחוזרת איפוא הקושיה על שמואל!","\u0003אלא\u0004 יש לחזור מפירוש זה, ולומר כך: \u0003רישא\u0004 \u0005[בתחילה]\u0006 \u0003אין יכול להפר, ו\u0004המקרה הוא שאוסרת עצמה אף בפירות \u0003דקא מייתא\u0004 \u0005[שמביאה]\u0006 \u0003היא.\u0004"],["\u0003ומתניתין\u0004 \u0005[ומשנתנו]\u0006 כשיטת \u0003ר' יוסי היא,\u0004 המצמצם יותר בהגדרת עינוי נפש. ש\u0003אמר רב הונא: כוליה פרקין\u0004 \u0005[כל פרקנו\u0006 זה\u0005]\u0006 שיטת \u0003ר' יוסי היא,\u0004 ושמואל בשיטת חכמים אמר את דבריו. \u0003ו\u0004מכל מקום, אף לשיטת ר' יוסי \u0003מאי\u0004 \u0005[מה\u0006 פירוש\u0005]\u0006 האמור במשנתנו \u0003\"אין יכול להפר\" —\u0004 כוונתו: אין יכול להפר \u0003משום עינוי נפש, אבל מפר\u0004 משום \u0003נדרים שבינו לבינה.\u0004","\u0003אמר רב יהודה אמר שמואל: נדרה\u0004 האשה שלא תאכל \u0003משתי ככרות\u0004 לחם, ש\u0003באחת\u0004 מהן שהיא ככר נאה הריהי \u0003מתענה\u0004 אם לא תאכל ממנה, \u0003ובאחת\u0004 מהן שהיא פת קיבר ואינה חפצה בה \u0003אין\u0004 היא \u0003מתענה\u0004 אם לא תאכל ממנה, \u0003מתוך שהוא מפר ל\u0004ככר שהיא \u0003מתענה\u0004 בה, ככל נדרי עינוי נפש — \u0003מפר\u0004 גם \u0003לשאינו מתענה. ורב אסי אמר\u0004 בשם \u0003ר' יוחנן: מפר למתענה\u0004 בלבד, \u0003ואין מפר לשאין מתענה.\u0004","\u0003ואיכא דאמרי\u0004 \u0005[ויש שאומרים]\u0006 זאת בלשון אחרת: \u0003בעא מיניה\u0004 \u0005[שאל אותו]\u0006 \u0003רב אסי מר' יוחנן: נדרה משתי ככרות, באחת מתענה ובאחת אין מתענה, מהו\u0004 הדין? \u0003אמר ליה\u0004 \u0005[לו]:\u0006 \u0003מפר ל\u0004זו ש\u0003מתענה\u0004 בה, \u0003ואין מפר לשאין מתענה\u0004 בה.","\u0003איתיביה\u0004 \u0005[הקשה לו]:\u0006 \u0003האשה שנדרה בנזיר, והיתה\u0004 עוברת על נדרה; \u0003שותה יין, ומטמאה למתים —\u0004"],["\u0003הרי זו סופגת את הארבעים\u0004 (לוקה ארבעים מלקות, כדין העובר על סתם \"לאו\" שבתורה), משום שעברה על האיסורים החלים על הנזיר. \u0003הפר לה בעלה\u0004 את נדר הנזירות \u0003והיא לא ידעה שהפר לה, והיתה שותה יין ומיטמאה למתים —\u0004 \u0003אינה סופגת את הארבעים,\u0004 שהרי לא עברה על איסורי נזיר, כיון שהופר נדרה.","\u0003ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003מפר\u0004 רק \u0003ל\u0004ככר ש\u0003מתענה\u0004 בה \u0003ואין מפר לשאין מתענה\u0004 בה, אם כן, גם כאשר הפר בעלה נדר נזירות, \u0003דלמא\u0004 \u0005[שמא]\u0006 רק \u0003מן יין דאית\u0004 \u0005[שיש]\u0006 \u0003לה צערא\u0004 \u0005[צער]\u0006 כשאינה שותה אותו — \u0003הפר לה,\u0004 אבל \u0003מן חרצן ומן זג —\u0004 \u0003לא הפר לה, דהא לא אית\u0004 \u0005[שהרי אין]\u0006 \u0003לה צערא\u0004 \u0005[צער]\u0006 אם לא תאכלם. \u0003ו\u0004כיון שגם אכילת חרצן וזג נאסרת בכלל הנזירות, אם אכלה אותם \u0003תספוג את הארבעים!\u0004","\u0003אמר רב יוסף:\u0004 כאן שונה הדבר, משום ש\u0003אין נזירות לחצאין,\u0004 שאין אדם יכול להיות נזיר ולאסור עצמו רק בחלק מאיסורי הנזירות, ומשום כך כשהפר לה בטלה הנזירות כולה. אבל אם היתה נודרת נדר סתם — יכול הבעל להפר רק את החלק שיש לה עינוי בו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 האם אפשר לדייק מדבריך שאכן אין נזירות לחצאין, ואולם, \u0003הא\u0004 \u0005[הרי]\u0006 \u0003קרבן לחצי נזירות איכא\u0004 \u0005[יש]?!\u0006 \u0003אלא אמר אביי:\u0004 יש לתקן ולומר: \u0003אין נזירות לחצאין, ואין קרבן לחצאין.\u0004","\u0003מיתיבי\u0004 \u0005[מקשים]\u0006 על כך ממה ששנינו: \u0003האשה שנדרה בנזיר והפרישה בהמתה\u0004 לקרבן נזיר \u0003ואחר כך הפר לה בעלה\u0004 את נדר הנזירות — \u0003מביאה חטאת העוף, ואינה מביאה עולת העוף. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 \u0003אין קרבן לחצי נזירות, אמאי\u0004 \u0005[מדוע]\u0006 \u0003מביאה חטאת העוף?\u0004","ודוחים: \u0003ואלא מאי\u0004 \u0005[מה]\u0006 תאמר — ש\u0003יש קרבן לחצי נזירות?\u0004 אם כן \u0003שלש בהמות בעי לאתויי\u0004 \u0005[צריכה\u0006 היא \u0005להביא]\u0006 \u0003חטאת עולה ושלמים,\u0004 כדין נזיר שהשלים את נזירותו! \u0003אלא, לעולם אין קרבן לחצי נזירות. וחטאת העוף דמתיא\u0004 \u0005[שמביאה]\u0006 — \u0003משום\u0004 ש\u0003חטאת\u0004 העוף באה גם \u0003על הספק,\u0004 לכן מביאה אותה גם על מקצת נזירות שנהגה.","וחוזרים לדיון העיקרי, \u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 רב אסי לר' יוחנן עוד ממה ששנינו: \u0003האשה שנדרה בנזיר ונטמאת, ואחר כך הפר לה בעלה —\u0004 \u0003מביאה חטאת העוף ואין מביאה עולת העוף. ואי אמרת\u0004 \u0005[ואם אומר אתה]\u0006 ש\u0003מפר\u0004 רק \u0003ל\u0004דבר ש\u0003מתענה\u0004 בו \u0003ואין מפר לשאין מתענה\u0004 בו,"],["\u0003דלמא\u0004 \u0005[שמא]\u0006 רק \u0003מיין דאית\u0004 \u0005[שיש]\u0006 \u0003לה צערא\u0004 \u0005[צער]\u0006 כשאינה שותה יין — \u0003הפר לה,\u0004 אבל \u0003מטומאת מת, דלית\u0004 \u0005[שאין]\u0006 \u0003לה צערא\u0004 \u0005[צער]\u0006 כשאינה נטמאת למת — \u0003לא הפר לה,\u0004 ומדוע אינה מביאה קרבן כנזיר שנטמא? ומכאן שמתוך שמפר למה שמתענה בו, מפר אף לשאינה מתענה בו!","ודוחים: \u0003אמרי\u0004 \u0005[אומרים]:\u0006 הנודרת \u0003מטומאת מת נמי אית\u0004 \u0005[גם כן יש]\u0006 \u0003לה צערא\u0004 \u0005[צער]\u0006 בכך, ומדוע — \u0003דכתיב\u0004 \u0005[שנאמר]:\u0006 \u0003\"והחי יתן אל לבו\"\u0004 (קהלת ז, ב), \u0003ותניא\u0004 \u0005[ושנויה\u0006 ברייתא\u0005]\u0006 \u0003היה ר' מאיר אומר: מאי דכתיב\u0004 \u0005[מהו שנאמר]\u0006 \u0003\"והחי יתן אל לבו\" —\u0004 כוונתו זה \u0003דיספוד\u0004 \u0005[שסופד]\u0006 לאחרים בפטירתם — \u0003יספדון ליה\u0004 \u0005[יספדו לו]\u0006 בעת פטירתו, \u0003דיבכון\u0004 \u0005[\u0006מי \u0005שבוכה]\u0006 על פטירת אחרים — \u0003יבכון ליה\u0004 \u0005[יבכו לו],\u0006 מי \u0003דיקבר\u0004 \u0005[שקובר]\u0006 אחרים — \u0003יקברוניה\u0004 \u0005[יקברו אותו]\u0006 ואם היא אסורה להיטמא למתים ואינה הולכת ללוויות הריהי מצטערת בכך כשחושבת כי משום כך גם בה לא יטפלו לאחר מותה, ולכן יש בכך משום עינוי נפש ויכול להפר. ואין מכאן קושיה לר' יוחנן.","נדרה האשה \u0003\"קונם שאני נהנה\u0004 (נהנית) \u0003לבריות\u0004 (מן הבריות)\" — \u0003אינו יכול להפר\u0004 לה את הנדר הזה, \u0003ו\u0004למרות נדר זה \u0003יכולה היא\u0004 אם היא עניה \u0003ליהנות ב\u0004מה שאדם מצווה להניח לעניים: \u0003לקט,\u0004 שיבולים בודדות שנפלו בשעת הקצירה, \u0003שכחה,\u0004 אלומה שנשכחה בשדה, \u0003ובפאה\u0004 שמניח אדם בסוף שדהו. שאין בכך הנאה מן הבריות, משום שמתנות אלה אינה מקבלת בחסדו של אדם אלא מפני מצות ה' וזכייתם מן ההפקר.","אמר אדם \u0003\"קונם כהנים לוים נהנים לי\" —\u0004 \u0003יטלו\u0004 מתנות כהונה ולוויה משלו \u0003על כרחו.\u0004 אבל אם אמר \u0003\"כהנים אלו ולוים אלו נהנים לי\" —\u0004 \u0003יטלו אחרים.\u0004","שנינו שאשה שנדרה שלא ליהנות מן הבריות אין בעלה יכול להפר לה, ומסיקים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 \u0003אפשר דמתזנה מדיליה\u0004 \u0005[שתיזון משלו],\u0006 שבעלה הוא שיפרנסנה, ולא תיהנה מאחרים. \u0003מכלל\u0004 הדברים אתה לומד ש\u0003בעל לאו\u0004 \u0005[לא]\u0006 \u0003בכלל בריות הוא,\u0004 שאף שאמרה \"בריות\" לא כללה בכך את בעלה. אולם, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה\u0006 של אותה הלכה\u0005]:\u0006 \u0003יכולה ליהנות בלקט שכחה ופאה,\u0004 ונדייק מכאן: \u0003אבל מ\u0004של \u0003בעל לא אכלה\u0004 \u0005[אוכלת],\u0006 \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003בעל בכלל בריות הוא\u0004 וגם בהנאתו נאסרת בנדרה!","\u0003אמר עולא: לעולם\u0004 תפרש שהבעל \u0003לאו\u0004 \u0005[לא]\u0006 \u0003בכלל בריות הוא,\u0004 ואין לדייק מן המשנה ולמצוא בה סתירה, אלא מצויים כאן שני טעמים מפני מה אינו יכול להפר; טעם אחד שלא נאמר בפירוש — שהיא יכולה להתפרנס מבעלה, \u0003ועוד\u0004 טעם מפורש ש\u0003אין יכול להפר —\u0004 \u0003מפני שיכולה ליהנות בלקט שכחה ופאה.\u0004","\u0003רבא אמר\u0004 להיפך: \u0003לעולם\u0004 תאמר ש\u0003בעל בכלל בריות הוא, ומה טעם קאמר\u0004 \u0005[\u0006הוא \u0005אומר]\u0006; \u0003מה טעם אין יכול להפר —\u0004 \u0003מפני שיכולה ליהנות בלקט שכחה ופאה.\u0004","\u0003רב נחמן אמר: לעולם בעל לאו\u0004 \u0005[לא]\u0006 \u0003בכלל בריות הוא,\u0004 וכשנדרה מן הבריות לא נדרה ממנו, ומשום כך אינו יכול להפר. \u0003והכי קתני\u0004 \u0005[וכך\u0006 הוא \u0005שונה]\u0006 את ההמשך: ואף אם \u0003נתגרשה\u0004 ואינה יכולה ליהנות עוד מבעלה, שהרי אז הוא נכלל בתוך \"בריות\", \u0003יכולה\u0004 עדיין \u0003ליהנות בלקט שכחה ופאה.\u0004"],["\u0003איתיביה\u0004 \u0005[הקשה לו]\u0006 \u0003רבא לרב נחמן: ובעל לאו\u0004 \u0005[לא]\u0006 \u0003בכלל בריות הוא? והתנן\u0004 \u0005[והרי שנינו\u0006 במשנה\u0005]:\u0006 האומרת \u0003\"נטולה אני\u0004 (אסורה הנאתי) \u0003מן היהודים\",\u0004 לענין תשמיש — \u0003יפר חלקו, ותהא משמשתו, ותהא נטולה מן היהודים\u0004 כאשר תתגרש. ומעתה, אם אתה אומר שבעלה בכלל נדר זה, נמצא שיש בכך נדר שבינו לבינה, ולכן מפר את חלקו, אבל אין הנדר מופר לעולם, ולכן כשמתגרשת ממנו נאסרת, ונטולה מן היהודים.","\u0003ואי אמרת\u0004 \u0005[ו\u0006אולם \u0005אם אומר אתה]\u0006 כי \u0003בעל לאו\u0004 \u0005[לא]\u0006 \u0003בכלל בריות הוא\u0004 אם כן אין זה נדר שבינו לבינה, אלא \u0003נדרי עינוי נפש הן, ויפר לה לעולם!\u0004","השיב לו: \u0003אימא\u0004 \u0005[אומר]\u0006 \u0003לך:\u0004 בדרך כלל בעל אינו בכלל בריות, ו\u0003שאני הכא\u0004 \u0005[שונה כאן]\u0006 \u0003דמוכחא מלתא\u0004 \u0005[שמוכח הדבר]\u0006 שהרי \u0003על היתרא קאסרה נפשה\u0004 \u0005[המותר\u0006 לה \u0005היא אוסרת\u0006 את \u0005עצמה]\u0006 ולא על יחסים שממילא אסורים עליה, ובודאי התכוונה לאסור עליה את בעלה בנדר זה.","שנינו במשנה שאם נדרה הנאה מן הבריות \u0003יכולה ליהנות בלקט שכחה ופאה.\u0004 ומעירים: \u0003ולא קתני\u0004 \u0005[שנה]\u0006 גם \u0003ובמעשר עני. והתניא\u0004 \u0005[והרי שנינו]\u0006 \u0003בברייתא\u0004 הלכה זו ונוסף בה: \u0003ובמעשר עני!\u0004","\u0003אמר ר' יוסף: לא קשיא\u0004 \u0005[קשה]\u0006; \u0003הא\u0004 \u0005[זו]\u0006 — שיטת \u0003ר' אליעזר, הא\u0004 \u0005[זו] —\u0006 שיטת \u0003רבנן\u0004 \u0005[חכמים].\u0006 \u0003דתנן\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 במשנה\u0005],\u0006 \u0003ר' אליעזר אומר: אין אדם צריך\u0004 להפריש בפועל, ואף לא \u0003לקרות שם על\u0004 חלקו של \u0003מעשר עני\u0004 בתבואה \u0003של דמאי\u0004 (תבואה הנלקחת מעם הארץ, שספק אם היא מעושרת). שהרי מעשר עני אין בו קדושה, ואף אין העני יכול לתובעו ממנו, שהרי אין בידו ראיה שמגיע לו."],["\u0003וחכמים אומרים: קורא שם,\u0004 שצריך לייחד חלק מן התבואה לצורך זה, ולקרוא עליה שם של מעשר עני, \u0003ואין צריך להפריש\u0004 ולתת בפועל את המעשר הזה, שכיון שהוא מופרש רק מספק, אין העני יכול לקבלו אלא אם כן יביא ראיה שהמעשר הוא שלו. \u0003מאי לאו\u0004 \u0005[האם לא]\u0006 נאמר כי \u0003למאן דאמר\u0004 \u0005[ל\u0006דעת \u0005מי שאומר]\u0006 אפילו \u0003ספקו\u0004 של מעשר עני \u0003טובל,\u0004 כלומר, אם אין מפרישים אותו נעשית התבואה טבל, ולכן צריך להפריש ולתת בפועל, ומשום שיש בכך חובת נתינה, \u0003קסבר\u0004 \u0005[סבור]:\u0006 \u0003אית ליה\u0004 \u0005[יש לו]\u0006 לנותן את מעשר העני \u0003טובת הנאה,\u0004 שיכול לתתו למי שירצה, ואף יכול לקבל שכר כלשהו עבור כך, \u0003וכיון דאית ליה\u0004 \u0005[שיש לו]\u0006 לנותן \u0003טובת הנאה —\u0004 \u0003לא מהניא\u0004 \u0005[מועילה]\u0006 העצה להנות ממעשר עני, שהרי יש בכך הנאה מן הבריות, ואינו יכול להתפרנס בדרך זו.","\u0003ולמאן דאמר\u0004 \u0005[ול\u0006דעת \u0005מי שאומר]\u0006 \u0003[אינו]\u0004 \u0003קורא שם,\u0004 הרי זה משום שהוא \u0003קסבר\u0004 \u0005[סבור]:\u0006 \u0003ספקו\u0004 של מעשר עני \u0003אינו טובל, וכל שספקו אינו טובל —\u0004 \u0003לית ליה\u0004 \u0005[אין לו]\u0006 לנותן \u0003טובת הנאה, ו\u0004מי שנדר מן הבריות \u0003שרי ליה לאיתהנויי\u0004 \u0005[מותר לו ליהנות]\u0006 ממעשר עני.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 ראיה זו אפשר לדחות, ולומר \u0003דכולי עלמא\u0004 \u0005[ש\u0006לדעת \u0005הכל]\u0006 \u0003ספקו\u0004 של מעשר עני \u0003טובל, ו\u0004אילו \u0003ר' אליעזר ורבנן\u0004 \u0005[וחכמים]\u0006 \u0003בהא קמיפלגי\u0004 \u0005[בזה\u0006 הם \u0005חלוקים]\u0006; \u0003ר' אליעזר סבר: לא נחשדו עמי הארץ על מעשר עני\u0004 והם מפרישים אותו, ולכן כאשר לוקח תבואה מעם הארץ (שהיא הדמאי) אינו צריך לחשוש שלא הופרש ממנה מעשר זה. וטעמו של ר' אליעזר הסובר שעמי הארץ מפרישים מעשר עני — \u0003כיון\u0004 ש\u0003אילו מפקר נכסיה והוי\u0004 \u0005[\u0006הוא \u0005מפקיר\u0006 את \u0005נכסיו והריהו]\u0006 נעשה בכך \u0003עני ושקל ליה\u0004 \u0005[ולוקח אותו]\u0006 את מעשר העני \u0003הוא\u0004 עצמו — \u0003לית ליה פסידא\u0004 \u0005[אין לו הפסד]\u0006 בדבר — משום כך נאמן לומר שהפריש מעשר זה.","\u0003ורבנן סברי\u0004 \u0005[וחכמים סבורים]:\u0006 אף על פי שקיימת דרך שכזו להימנע מלתת בפועל את המעשר, אין היא מצוייה, כי \u0003נכסיה לא מפקר איניש\u0004 \u0005[\u0006את \u0005נכסיו\u0006 \u0005אין אדם מפקיר]\u0006 לשם כך, מפני \u0003דמירתת דלמא זכי בהו איניש אחרינא\u0004 \u0005[שמפחד שמא יזכה בהם\u0006 בינתיים \u0005אדם אחר].\u0006 \u0003הלכך\u0004 (משום כך), משום שאין דרך זו של הפקרת נכסים מצוייה, והמקיים מצות הפרשה יש לו בכך הפסד — לכן \u0003נחשדו\u0004 עמי הארץ על מעשר עני. ולפי זה הברייתא המתירה לנודר מן הבריות ליהנות ממעשר עני אינה מובנת עדיין.","\u0003רבא אומר\u0004 שאפשר להסביר את הסתירה במקורות לענין הנאה ממעשר עני בדרך אחרת בלא להזקק למחלוקת תנאים: \u0003כאן,\u0004 במשנתנו, מדובר \u0003במעשר עני המתחלק בתוך הבית,\u0004 שהביאו אותו הביתה ומחלקים אותו לעניים הבאים אל הבית, \u0003דכתיבא ביה\u0004 \u0005[שנאמרה בו]\u0006 \u0003נתינה,\u0004 ככתוב: \u0003\"ונתתה ללוי לגר\u0004 ליתום ולאלמנה\u0003\"\u0004 (דברים כו, יב) ובזה יש רשות לבעל הבית לתת לעני שירצה, ויש לו טובת הנאה מזה — \u0003משום הכי\u0004 \u0005[כך]\u0006 \u0003אסור ליה\u0004 \u0005[לו]\u0006 \u0003לאיתהנויי\u0004 \u0005[ליהנות]\u0006 ממעשר עני אם נדר שלא יהנה מן הבריות.","ואילו \u0003כאן,\u0004 בברייתא, מדובר \u0003במעשר עני המתחלק בתוך הגרנות. כיון דכתיב ביה\u0004 \u0005[שנאמר בו]\u0006 \u0003\"והנחת בשעריך\"\u0004 (דברים יד, כח) אינו יכול לתת אותו לאדם מסויים, אלא כל עני שבא לוקח ממנו, וכיון שאין לנותן טובת הנאה בזה, לכן המודר הנאה מן הבריות \u0003שרי ליה לאיתהנויי\u0004 \u0005[מותר לו ליהנות].\u0006","שנינו במשנה: האומר \"קונם \u0003כהנים ולוים נהנין לי —\u0004 \u0003יטלו\u0004 הם בעל כרחו\". ושואלים: \u0003אלמא\u0004 \u0005[מכאן]\u0006 אתה יכול להסיק ש\u0003טובת הנאה אינה\u0004 נחשבת \u0003ממון\u0004 ממש.","שאותה הנאה שיש לנותן, במה שיכול לתת תרומותיו ומעשרותיו לכהנים ולוויים מסויימים, ויכול אף לקבל גמול עבור זה — אינה נחשבת כממון, ולכן יטלו בעל כרחו, ואין אומרים שהוא מהנה אותם. אולם, \u0003אימא סיפא\u0004 \u0005[אמור\u0006 את \u0005סופה]\u0006 של המשנה: \u0003\"\u0004קונם \u0003כהנים אלו ולוים אלו נהנין לי\" —\u0004 \u0003יטלו אחרים, אבל להני\u0004 \u0005[לאלה]\u0006 שנדר מהם — \u0003לא\u0004 יתן. \u0003אלמא\u0004 \u0005[מכאן]\u0006 ש\u0003טובת הנאה\u0004 נחשבת \u0003ממון,\u0004 ולכן יכול לאסור עליהם ליהנות ממנו!","\u0003אמר רב הושעיא: לא קשיא\u0004 \u0005[אין\u0006 זה \u0005קשה]\u0006; \u0003הא\u0004 \u0005[זו]\u0006 — כשיטת \u0003רבי, והא\u0004 \u0005[וזו]—\u0006 כשיטת \u0003ר' יוסי בר' יהודה.\u0004 ומהי המחלוקת הזו? \u0003דתניא\u0004 \u0005[ש\u0006כן \u0005שנינו\u0006 בברייתא\u0005]:\u0006 \u0003הגונב טבלו של חבירו ואכלו —\u0004 \u0003משלם לו דמי טבלו,\u0004 שצריך להשיב לו בשווי כל מה שגנב, אלו \u0003דברי רבי. ר' יוסי בר' יהודה אומר: אינו משלם אלא דמי חולין שבו,\u0004 אבל אינו צריך להחזיר לו את חלק התרומות והמעשרות שהיה בטבל זה, שהרי חלק זה אינו שייך בעצם לחבירו. \u0003מאי לאו בהא קמיפלגי\u0004 \u0005[האם לא ב\u0006ענין \u0005זה\u0006 הם \u0005חלוקים]\u0006"],["\u0003רבי סבר: טובת הנאה\u0004 נחשבת \u0003ממון\u0004 ולכן צריך הגנב להחזיר לו את הטבל כולו — מפני שיש לבעל הטבל גם זכות ממונית במתנות, שנהנה מטובת הנאה כאשר הוא נותן את התרומה והמעשר שלו לכהנים ולוויים מסויימים. \u0003ו\u0004אילו \u0003ר' יוסי בר ר' יהודה סבר: טובת הנאה אינה\u0004 נחשבת \u0003ממון\u0004 ולכן אין לבעל התבואה כל זכות ממונית בחלק התרומה והמעשר?","ודוחים: \u0003לא,\u0004 אפשר לומר \u0003דכולי עלמא\u0004 \u0005[ש\u0006לדעת \u0005הכל]\u0006 \u0003טובת הנאה אינה\u0004 נחשבת \u0003ממון. אלא הכא\u0004 \u0005[כאן]\u0006 \u0003במתנות ש\u0004עדיין \u0003לא הורמו\u0004 (הופרשו) \u0003קא מיפלגי\u0004 \u0005[\u0006הם \u0005חלוקים].\u0006 והשאלה היא האם מתנות הכהן והלוי שעדיין לא הופרשו בפועל נחשבות כאילו כבר הפרישו אותן. שאם הן נחשבות כבלתי מופרשות — צריך להשיב לו כל מה שגנב ממנו. אבל אם הן נחשבות כמופרשות, נמצא שהגנב לא לקח ממנו עצמו אלא רק את חלק החולין, שהרי המתנות אינן שלו כלל.","ודוחים: \u0003ואי\u0004 \u0005[ואם]\u0006 \u0003טובת הנאה אינה\u0004 נחשבת \u0003ממון —\u0004 \u0003מה לי\u0004 אם כבר \u0003הורמו, מה לי\u0004 אם עדיין \u0003לא הורמו?\u0004 והרי מכל מקום אין לבעל התבואה כל זכות ממונית בחלק התרומה שבטבל!","\u0003אלא\u0004 כך צריך לומר: \u0003היינו טעמא\u0004 \u0005[זהו הטעם]\u0006 של \u0003רבי\u0004 \u0005:\u0006 \u0003קנסוה רבנן\u0004 \u0005[קנסו חכמים]\u0006 \u0003לגנב כי היכי\u0004 כדי ש\u0003לא ליגנוב\u0004 \u0005[יגנוב]\u0006 שוב, ולכן צריך לשלם לבעל הטבל הנגנב הכל, אף שלבעל הטבל עצמו אין טובת הנאה בחלק המתנות. \u0003ור' יוסי בר ר' יהודה סבר: קנסוה רבנן\u0004 \u0005[קנסו חכמים]\u0006 \u0003לבעל הבית\u0004 שיקבל רק את דמי החולין, \u0003כי היכי\u0004 \u0005[כדי]\u0006 שלהבא \u0003לא לישהי לטיבליה\u0004 \u0005[ישהה את טבלו],\u0006 שלא יהא רגיל להשהות בידו תבואה בלתי מעושרת, שהרי אם היה נותן מיד את מתנותיו לא היה מגיע לכלל גניבה. ואף אם היתה לו טובת הנאה — קונסים אותו שלא יהנה ממנה.","\u0003רבא אמר\u0004 שאפשר להסביר את הסתירה במשנתנו בדרך אחרת: כפי שדייקנו מן המקרה השני (כהנים אלו — יטלו אחרים) טובת הנאה הריהי ממון, ואולם \u0003שאני\u0004 \u0005[שונה]\u0006 \u0003תרומה, דהיינו טעמא\u0004 \u0005[שזהו הטעם]\u0006 ש\u0003יטלו על כרחו\u0004 אם אסר אותה על הכהנים כולם — \u0003משום\u0004 ש\u0003תרומה\u0004 \u0003לא חזיא\u0004 \u0005[ראויה]\u0006 \u0003אלא לכהנים, וכיון דקא אתי למיסרא עלייהו\u0004 \u0005[שהוא\u0006 \u0005בא לאסור אותה עליהם]\u0006 על ידי נדרו, ואין לה שימוש אלא לכהנים, אם כן הריהו, איפוא \u0003שויא עפרא בעלמא\u0004 \u0005[עשה אותה,\u0006 מבחינתו, כ\u0005עפר סתם].\u0006 שאם היא אסורה לכהנים, והישראלים גם בלא נדרו אסורים לאכול ממנה, אם כן נמצא שביטל רשותו ממנה לגמרי, ושוב אין לומר שיש לכהנים הנאה ממנו.","אמרה אשה \u0003\"קונם שאיני עושה\u0004 דבר \u0003על פי\u0004 (לצורך) \u0003אבא\u0004 שלי \u0003\",\u0004 או שאמרה \u0003\"\u0004קונם שאיני עושה דבר \u0003על פי אביך\",\u0004 או \u0003\"על פי אחי\",\u0004 או \u0003\"על פי אחיך\" —\u0004 \u0003אינו יכול להפר,\u0004 שאין נדרים אלה בכלל דברים שבינו לבינה. אם אמרה \u0003\"שאיני עושה על פיך\"\u0004 שאינה עושה מלאכה המוטלת עליה לעשותה מכוח הכתובה — \u0003אינו צריך\u0004 כלל \u0003להפר,\u0004 אלא הנדר בטל מעצמו, משום שיש עליה התחייבות מוקדמת, מכוח הנישואין, לעשות עבורו.","\u0003ר' עקיבא אומר: יפר\u0004 את הנדר, \u0003שמא תעדיף עליו יותר מן הראוי לו,\u0004 שאם תוסיף ותעשה לו מלאכה יותר מן הקיצבה הקבועה לה בהלכה, הרי לגבי חלק זה אין לו בעלות, וחל הנדר, והוא עלול להיכשל וליהנות מדבר האסור לו.","\u0003ר' יוחנן בן נורי אומר: יפר\u0004 מטעם אחר, \u0003שמא יגרשנה\u0004 ואז בטלה התחייבותה לו \u0003ותהי אסורה עליו\u0004 לעולם בהנאה ממעשה ידיה, וכדי שלא יבוא בעתיד לידי מכשול, יפר את הנדר בעודה נשואה.","\u0003אמר שמואל: הלכה כר' יוחנן בן נורי.\u0004 ושואלים: \u0003למימרא דקסבר\u0004 \u0005[האם לומר,\u0006 להסיק מכאן, \u0005שסבור]\u0006 \u0003שמואל\u0004 כי \u0003אדם מקדיש דבר שלא בא לעולם?\u0004 שהרי לדעת ר' יוחנן בן נורי חל איסור הנדר על דברים שתעשה בעתיד, כאשר תתגרש — שהיא מציאות שאינה קיימת עדיין. \u0003ורמינהי\u0004 \u0005[ומשליכים,\u0006 מראים סתירה\u0005]\u0006 ממה ששנינו: \u0003המקדיש מעשה ידי אשתו\u0004 —"],["\u0003הרי זו\u0004 האשה \u0003עושה ואוכלת,\u0004 שאין ההקדש חל על הדברים הללו. \u0003והמותר,\u0004 אם עשתה יותר מכדי דמי אכילתה — \u0003ר' מאיר אומר:\u0004 המותר נעשה באמת \u0003הקדש, ר' יוחנן הסנדלר אומר: חולין\u0004 הוא. \u0003ואמר שמואל: הלכה כר' יוחנן הסנדלר. אלמא\u0004 \u0005[מכאן]\u0006 שדעת שמואל היא ש\u0003אין אדם מקדיש דבר שלא בא לעולם,\u0004 ומשום כך לא חל כלל הקדש על מה שתעשה בעתיד.","\u0003וכי תימא\u0004 \u0005[ואם תאמר]\u0006 : \u0003כי קאמר\u0004 \u0005[כאשר אומר]\u0006 שמואל ש\u0003הלכה כר' יוחנן בן נורי\u0004 במשנתנו — רק \u0003על\u0004 ענין \u0003העדפה הוא דקאמר\u0004 \u0005[שאומר],\u0006 שלדעתו גם מה שמעדיפה שייך לבעל ואינה יכולה לאוסרו עליו, ואז אין הדברים עומדים בסתירה לשיטת ר' יוחנן הסנדלר לגבי הקדשת מעשה ידי אשתו.","אולם אם כן \u0003לימא\u0004 \u0005[שיאמר]\u0006 בצורה ברורה: \u0003הלכה כר' יוחנן בן נורי בהעדפה. אי נמי\u0004 \u0005[או גם כן]\u0006 יאמר: \u0003הלכה כתנא קמא\u0004 הסבור אף הוא שההעדפה של הבעל. \u0003אי נמי\u0004 \u0005[או גם כן]\u0006 יאמר: \u0003(אין) הלכה כר' עקיבא\u0004 הסבור שההעדפה היא שלה!","\u0003אלא אמר רב יוסף:\u0004 כך יש ליישב את הסתירה בדברי שמואל; שאף שאין אדם יכול להקדיש דבר שלא בא לעולם, מכל מקום \u0003שאני\u0004 \u0005[שונים]\u0006 \u0003קונמות, הואיל ואדם אוסר\u0004 אפילו \u0003פירות חבירו\u0004 \u0003עליו\u0004 (על עצמו), למרות שהפירות הללו לא הגיעו עדיין לרשותו — \u0003אוסר נמי\u0004 \u0005[גם כן]\u0006 בקונמות \u0003דבר שלא בא לעולם עליו\u0004 על עצמו, למרות שעוד לא בא לעולם. מה שאין כן בהקדש, שאין אדם יכול להקדיש דבר שאינו ברשותו.","\u0003אמר ליה\u0004 \u0005[לו]\u0006 \u0003אביי:\u0004 זו אינה ראיה כלל, כי \u0003בשלמא\u0004 \u0005[נניח]\u0006 ש\u0003אדם אוסר פירות חבירו עליו\u0004 שכן יש בכוחו של אדם לאסור בקונם דבר שיש לו זכות מסויימת בו, \u0003שהרי אדם אוסר פירותיו על חבירו,\u0004 שכשם שיש לו רשות על הפירות של עצמו ויכול לאוסרם על אחרים — כך יש לו רשות על גופו שלו לאסור דבר של אחרים עליו. \u0003אלא\u0004 האם \u0003יאסור\u0004 גם \u0003דבר שלא בא לעולם על חבירו? שהרי אין אדם אוסר פירות חבירו על חבירו\u0004 שגם החבר וגם פירותיו אינם ברשותו. והרי במשנתנו אסרה האשה בקונם את מעשי ידיה שלא באו לעולם על אחר — על בעלה!","\u0003אלא אמר רב הונא בריה\u0004 \u0005[בנו]\u0006 של \u0003רב יהושע:\u0004 כאן מדובר \u0003ב\u0004אשה ה\u0003אומרת \"יקדשו ידי לעושיהן\"\u0004 (לקדוש ברוך הוא, שהוא עושה הכל) ואין כאן ענין של דבר שלא בא לעולם, כיון ש\u0003ידים הא איתנהו\u0004 \u0005[הרי ישנן]\u0006 \u0003בעולם.\u0004","ושואלים מצד אחר: \u0003וכי אמרה הכי\u0004 \u0005[וכאשר\u0006 היא \u0005אומרת כך] —\u0006 \u0003קדשה\u0004 \u0005[מתקדשים\u0006 הדברים\u0005]\u0006? \u0003והא משעבדן\u0004 \u0005[והרי משועבדות]\u0006 \u0003ידיה לבעל\u0004 לעשות לו מלאכה שנתחייבה בה! ומשיבים: \u0003דאמרה\u0004 \u0005[ש\u0006היא \u0005אומרת]:\u0006 \u0003לכי מגרשה\u0004 \u0005[לכאשר אתגרש]\u0006 יחול הנדר. ומקשים: \u0003השתא מיהת לא מגרשה\u0004 \u0005[עכשיו על כל פנים אינה מגורשת],\u0006 \u0003וממאי דכי אמרה הכי מהניא\u0004 \u0005[וממה,\u0006 מניין לנו \u0005שכאשר\u0006 היא \u0005אומרת כך —\u0006 \u0005מועיל\u0006 הדבר\u0005]\u0006 שיכולה להקדיש דבר ולא יחול ההקדש אלא רק לעתיד?"]]};
